local PUI = _G.PhoenixUI if not (PUI and PUI.gateOpen) then return end
-- zhTW translations (PUI_V2 5.17). Keys are the English strings Phoenix renders
-- (/pui loc lists coverage; .tools/locales.py writes ../keys.txt, and
-- .tools/locale_tokens.py checks every format spec, escape and slash command
-- survives). Game terms follow the Traditional Chinese client's own wording.
-- Any string not listed falls back to English.
PUI.Locale:Add("zhTW", {
  ["+2 / +3 marks on the timer bar"] = "計時條上的 +2 / +3 標記",
  ["/gg"] = "/gg",
  ["/gg message"] = "/gg 訊息",
  ["/keys command"] = "/keys 命令",
  ["/pui council <item> asks your group Need, Minor, Transmog or Pass; answers come back with item level. Others need Phoenix with Council on."] = "/pui council <物品> 向隊伍詢問需求、小幅提升、幻化或放棄；回覆附帶物品等級。其他人需要開啟 Council 的 Phoenix。",
  ["/pui pull [s] (also /pui cd), /pui break [min], /pui rc."] = "/pui pull [秒]（也可 /pui cd）、/pui break [分鐘]、/pui rc。",
  ["/pui rl"] = "/pui rl",
  ["/pui simc opens your character as a SimulationCraft profile, ready to copy into SimulationCraft or Raidbots."] = "/pui simc 將你的角色開啟為 SimulationCraft 配置，可直接複製到 SimulationCraft 或 Raidbots。",
  ["0 = off. Errors seen in 3 or more sessions become your baseline; when this many errors outside the baseline happen in one session, one chat line says so (once per session)."] = "0 = 關閉。在 3 次或更多會話中出現的錯誤成為基線；一次會話中出現這麼多基線外錯誤時，聊天中會有一行提示（每次會話一次）。",
  ["0 keeps the summary card open until you close it."] = "0 表示摘要卡片保持開啟，直到你關閉它。",
  ["0 makes the bar background invisible."] = "0 使計量條背景不可見。",
  ["0 poor, 1 common, 2 uncommon, 3 rare, 4 epic, 5 legendary, 6 artifact, 7 heirloom."] = "0 粗糙，1 普通，2 優秀，3 精良，4 史詩，5 傳說，6 神器，7 傳家寶。",
  ["12.4K instead of 12,400."] = "顯示 12.4K 而不是 12,400。",
  ["24-hour clock"] = "24 小時制",
  ["24-hour clock block"] = "24 小時時鐘模組",
  ["24-hour time instead of AM/PM."] = "使用 24 小時制而不是上午/下午。",
  ["A 1 px theme border around each skinned button."] = "每個美化按鈕周圍 1 畫素的主題邊框。",
  ["A Phoenix button in the inbox that takes only the gold (no items, skips COD) from every mail."] = "收件箱中的 Phoenix 按鈕，只從每封郵件中提取金幣（不取物品，跳過付款取信）。",
  ["A Phoenix search box: items on the page that do not match fade."] = "Phoenix 搜尋框：頁面上不匹配的物品會變淡。",
  ["A banner with rising embers when you earn an achievement, time a key or level up. Reduced motion (Glows page) keeps only the banner."] = "獲得成就、限時完成鑰石或升級時顯示帶升騰餘燼的橫幅。減少動畫（光效頁面）時只保留橫幅。",
  ["A bar for spec resources that live in an aura (for example a stacking buff). Set the spell below."] = "用於存放在光環中的專精資源（例如可疊加的增益）的計量條。在下方設定法術。",
  ["A bar glows when the game marks the ability as about to happen (the timing comes from the game)."] = "當遊戲標記技能即將發生時計量條發光（時間來自遊戲）。",
  ["A bar that counts down to your next melee swing. Off by default; Forever only. It reads your own swings from the combat log."] = "倒數到你下一次近戰攻擊的計量條。預設關閉；僅限 Forever。從戰鬥記錄讀取你自己的攻擊。",
  ["A block of extra frames for every tank (or healer) in the group, in addition to the normal frames."] = "為隊伍中每個坦克（或治療）額外顯示的一組框架，不影響普通框架。",
  ["A bright edge when absorbs run past full health, and when heal absorbs eat more than the health left."] = "吸收量超過滿血時，以及治療吸收超過剩餘生命時顯示亮邊。",
  ["A bright line where the bar is draining."] = "計量條減少處的亮線。",
  ["A button in Blizzard's Edit Mode window that opens Phoenix Studio."] = "暴雪編輯模式視窗中開啟 Phoenix Studio 的按鈕。",
  ["A button on the panel that cancels your oldest application, so a new one fits under the limit of five. In combat it waits until combat ends."] = "面板上取消你最早申請的按鈕，以便新申請不超過五個的上限。戰鬥中會等到戰鬥結束。",
  ["A button that leaves the vehicle, shown only when you can exit."] = "離開載具的按鈕，僅在可以離開時顯示。",
  ["A class icon on each friend row."] = "每個好友行上的職業圖示。",
  ["A click on a window's header opens a Phoenix list of meter types instead of cycling through them."] = "點選視窗標題會開啟 Phoenix 的計量型別列表，而不是迴圈切換。",
  ["A clickable button beside quests that have a usable item (placed outside combat)."] = "在有可使用物品的任務旁顯示可點選按鈕（在非戰鬥中放置）。",
  ["A cog in the title bar of every skinned window opens its Phoenix options in place."] = "每個美化視窗標題欄中的齒輪可直接開啟其 Phoenix 選項。",
  ["A coloured dot for each party member targeting this enemy (shared with the party frames' enemy dots)."] = "每個以該敵人為目標的隊伍成員顯示一個彩色圓點（與隊伍框架的敵人圓點共用）。",
  ["A coloured glow around player, target, focus and boss frames when you have threat."] = "你有仇恨時，玩家、目標、專注目標和首領框架周圍顯示彩色光效。",
  ["A countdown bar under the dungeon and battleground ready pop-ups (same countdown as the minimap queue eye)."] = "地城和戰場就緒彈窗下方的倒計時條（與小地圖佇列之眼的倒計時相同）。",
  ["A countdown bar while you fly. The first flight on a route is timed and remembered."] = "飛行時的倒計時條。每條航線的首次飛行會被計時並記住。",
  ["A dark background behind the tracker."] = "追蹤器後的深色背景。",
  ["A faint bar on your row showing your best pull on this boss."] = "你的行上顯示你在該首領上最佳一次拉怪的淡色條。",
  ["A gold border around the enemy you are targeting."] = "你當前目標敵人周圍的金色邊框。",
  ["A green arrow on loot and rolls with a higher item level than what you wear."] = "物品等級高於當前裝備的拾取和擲骰上顯示綠色箭頭。",
  ["A grey cross when a cast is stopped before it finishes."] = "施法在完成前停止時顯示灰色叉號。",
  ["A hit on your target this soon after your cast counts as yours."] = "施法後這麼短時間內對目標的命中算作你的。",
  ["A key that hides or shows every meter window. Empty means no key."] = "隱藏或顯示所有計量視窗的按鍵。留空表示無按鍵。",
  ["A key that resets the meter data. Empty means no key."] = "重置計量資料的按鍵。留空表示無按鍵。",
  ["A key that switches on your \"While my layer key is active\" overrides (for example bigger nameplates or a different action bar page look). Leave empty for no key."] = "開啟你的“圖層按鍵啟用時”覆蓋設定的按鍵（例如更大的名條或不同的快捷列頁面外觀）。留空表示無按鍵。",
  ["A light Horde or Alliance tint behind Battle.net friends in World of Warcraft."] = "在《魔獸世界》中的Battle.net好友後顯示淡淡的部落或聯盟色調。",
  ["A line naming where arena frames, DR and queue status live."] = "一行說明競技場框架、遞減和佇列狀態的位置。",
  ["A popup grid that opens from the bin button, or a bar that is always shown along the minimap or wherever you move it."] = "從收納按鈕開啟的彈出網格，或沿小地圖（或你移動到的任何位置）始終顯示的條。",
  ["A progress bar for experience, your watched reputation or honor. Data Bars owns this bar."] = "經驗、追蹤聲望或榮譽的進度條。此條由資料條管理。",
  ["A red cross when a cast is interrupted."] = "施法被打斷時顯示紅色叉號。",
  ["A red mark on enchantable slots without an enchant."] = "可附魔但未附魔的欄位上顯示紅色標記。",
  ["A repeat inside this time is hidden when Hide repeated lines is on."] = "開啟“隱藏重複行”時，此時間內的重複會被隱藏。",
  ["A right click on the header opens a list of fights (current, overall, last saved) instead of cycling."] = "右鍵點選標題會開啟戰鬥列表（當前、總計、上次儲存），而不是迴圈切換。",
  ["A ring around your mouse cursor, so you never lose it in a busy fight."] = "滑鼠指標周圍的光環，讓你在混亂的戰鬥中不會丟失指標。",
  ["A row of small buttons (Say, Party, Instance, Raid, Guild, Officer, Whisper, 1, 2) that open the chat box on that channel."] = "一排小按鈕（說、隊伍、副本、團隊、公會、官員、密語、1、2），點選即在該頻道開啟聊天框。",
  ["A search box in the popup that narrows the buttons by name."] = "彈窗中的搜尋框，按名稱篩選按鈕。",
  ["A small badge with the number of new errors this session; click it to open the viewer."] = "顯示本次會話新錯誤數量的小徽章；點選開啟檢視器。",
  ["A small clock for the current fight. It is the one shared timer: the Embers title bar and the Mythic+ card read the same clock."] = "當前戰鬥的小時鐘。它是唯一共享的計時器：Embers 標題欄和傳奇鑰石卡片讀取同一個時鐘。",
  ["A small dot in the middle of the ring."] = "光環中心的小圓點。",
  ["A small frame for each enemy pet (click to target, right-click to focus)."] = "每個敵方寵物的小框架（點選設為目標，右鍵設為專注目標）。",
  ["A small list of the next boss abilities and their times during a boss fight. Move it in Studio."] = "首領戰中接下來首領技能及其時間的小列表。在 Studio 中移動。",
  ["A small mark on your focus."] = "你的專注目標上的小標記。",
  ["A small popup the first time a new error happens (repeats are only counted)."] = "新錯誤首次發生時的小彈窗（重複只計數）。",
  ["A small read-only Phoenix panel inside Blizzard's conquest frame with your title progress and conquest."] = "暴雪征服框架中的 Phoenix 只讀小面板，顯示你的頭銜進度和征服點數。",
  ["A soft glow around reminder icons."] = "提醒圖示周圍的柔和光效。",
  ["A soft shadow under Phoenix window text."] = "Phoenix 視窗文字下的柔和陰影。",
  ["A spell shown in the cooldown manager's Essential or Utility rows is hidden on your bars. Off while the cooldown manager hides icons that are on your bars (pick one)."] = "冷卻管理器“核心”或“輔助”行中顯示的法術會在你的快捷列上隱藏。冷卻管理器隱藏快捷列上已有的圖示時此項關閉（二選一）。",
  ["A starting look for size, spacing and icon side. Every part can still be changed on its own below."] = "大小、間距和圖示位置的起始外觀。下方每一項仍可單獨更改。",
  ["A strip of recent casts for arena 1."] = "競技場 1 的最近施法條。",
  ["A strip of recent casts for arena 2."] = "競技場 2 的最近施法條。",
  ["A strip of recent casts for arena 3."] = "競技場 3 的最近施法條。",
  ["A strip of recent casts for focus."] = "專注目標的最近施法條。",
  ["A strip of recent casts for party 1."] = "隊伍 1 的最近施法條。",
  ["A strip of recent casts for party 2."] = "隊伍 2 的最近施法條。",
  ["A strip of recent casts for party 3."] = "隊伍 3 的最近施法條。",
  ["A strip of recent casts for party 4."] = "隊伍 4 的最近施法條。",
  ["A strip of recent casts for target."] = "目標的最近施法條。",
  ["A strip of recent casts for you."] = "你的最近施法條。",
  ["A thin accent border on the friends frame and an accent line under the open tab."] = "好友框架上的細強調色邊框，以及開啟的標籤頁下的強調線。",
  ["A thin accent line at the right edge shows where you are while scrolled."] = "滾動時右邊緣的細強調線顯示你的位置。",
  ["A thin accent-coloured line under the health bar."] = "生命條下方的細強調色線。",
  ["A thin dark border around each icon."] = "每個圖示周圍的細深色邊框。",
  ["A white edge when a shield is bigger than the missing health, and a red edge when a heal absorb is bigger than the current health."] = "護盾大於損失生命時顯示白邊，治療吸收大於當前生命時顯示紅邊。",
  ["A/B report"] = "A/B 報告",
  ["Abilities listed"] = "列出的技能",
  ["Abilities the game only estimates show a ~ until their time is firm."] = "遊戲只能估算時間的技能會顯示 ~，直到時間確定。",
  ["Ability icon"] = "技能圖示",
  ["Ability substitutions"] = "技能替換",
  ["Accent colour"] = "強調色",
  ["Accent line"] = "強調線",
  ["Accept group invites from friends"] = "接受好友的組隊邀請",
  ["Accept group invites from guild"] = "接受公會的組隊邀請",
  ["Accept invites from friends"] = "接受好友的邀請",
  ["Accept role checks for me"] = "替我接受職責確認",
  ["Accepts a dungeon or raid finder role check with the roles you have set. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "以你設定的職責接受地城或團隊查詢器的職責確認。暴雪用受保護的程式碼執行此視窗；插件在此協助偶爾會導致“介面行為被阻止”訊息。因你的選擇預設開啟；如果看到該訊息請關閉。",
  ["Accepts and turns in quests with at most one reward choice. Hold the pause key to read the quest."] = "接受並交付最多隻有一個獎勵選項的任務。按住暫停鍵可閱讀任務。",
  ["Accepts group invites from WoW and Battle.net friends. Never while you are queued or in combat."] = "接受魔獸世界和Battle.net好友的組隊邀請。排隊或戰鬥中從不接受。",
  ["Accepts group invites from friends, Battle.net friends and guild members. While the Friends module is on, its own per-source switches decide instead."] = "接受好友、Battle.net好友和公會成員的組隊邀請。好友模組開啟時，改由其各來源開關決定。",
  ["Accepts group invites from guild members. Never while you are queued or in combat."] = "接受公會成員的組隊邀請。排隊或戰鬥中從不接受。",
  ["Achievements"] = "成就",
  ["Action bar 1"] = "快捷列 1",
