  ["Action bars: when another addon does this"] = "快捷列：當其他插件做此事時",
  ["Action button tooltips"] = "動作按鈕滑鼠提示",
  ["Action status text"] = "動作狀態文字",
  ["Actions can only be dragged off with the pick-up modifier (Shift by default)."] = "只有按住拾取修飾鍵（預設 Shift）才能拖走動作。",
  ["Activity on the row"] = "行上的活動",
  ["Add group size"] = "新增隊伍規模",
  ["Add on-use trinkets"] = "新增主動使用飾品",
  ["Add text slot: one line each, \"tag @ POINT x y size\" (for example health:percent @ TOPRIGHT 0 10 14)."] = "新增文字槽：每行一個，\"tag @ POINT x y size\"（例如 health:percent @ TOPRIGHT 0 10 14）。",
  ["Add your own character name to reports. Other players' names are never collected."] = "在報告中加入你自己的角色名。從不收集其他玩家的名字。",
  ["Add, remove and reorder columns. Column IDs: name, spec, damage, healing, kb, deaths, hk, rating, ratingChange, mmrBefore, mmrAfter, honor, plus any column another addon adds."] = "新增、移除和排序列。列 ID：name、spec、damage、healing、kb、deaths、hk、rating、ratingChange、mmrBefore、mmrAfter、honor，以及其他插件新增的任何列。",
  ["AddOn list"] = "插件列表",
  ["Addon compartment"] = "插件收納欄",
  ["Addon sections in the viewer open collapsed; click a section header to expand it."] = "檢視器中的插件分割槽預設摺疊；點選分割槽標題展開。",
  ["Adds ID lines (spell, item, NPC, quest and 23 more kinds) to tooltips. Phoenix is the only place IDs are added."] = "在滑鼠提示中新增 ID 行（法術、物品、NPC、任務及另外 23 種）。只有 Phoenix 新增 ID。",
  ["Adds Phoenix's own emoji: :smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:."] = "新增 Phoenix 自己的表情：:smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:。",
  ["Adds a Phoenix UI button above the Escape menu."] = "在 Esc 選單上方新增 Phoenix UI 按鈕。",
  ["Adds a Train all button to the class trainer."] = "在職業訓練師處新增“全部訓練”按鈕。",
  ["Adds a glow around the frame while the class icon shows an aura."] = "職業圖示顯示光環時，在框架周圍新增光效。",
  ["Adds channelled spells to the strip."] = "在施法條中加入引導法術。",
  ["Adds each row's share of the total when the game shows the numbers."] = "遊戲顯示數值時，新增每行佔總量的比例。",
  ["Adds gear from your bags as commented lines, so Raidbots Top Gear can compare it."] = "將揹包中的裝備作為註釋行加入，以便 Raidbots Top Gear 進行比較。",
  ["Adds guild name and rank to player tooltips."] = "在玩家滑鼠提示中新增公會名稱和會階。",
  ["Adds kills, wipes and your best time to the tooltip of a boss you have stats for."] = "在有統計資料的首領滑鼠提示中新增擊殺、團滅和你的最佳時間。",
  ["Adds roles in fixed order, class-coloured counts, age, leader score and decline memory to the group tooltip."] = "在隊伍滑鼠提示中按固定順序新增職責、職業著色人數、時長、隊長評分和拒絕記錄。",
  ["Adds the Phoenix score or item-level difference to item tooltips."] = "在物品滑鼠提示中新增 Phoenix 評分或物品等級差。",
  ["Adds the enemy forces of the enemies you are fighting to the forces line."] = "將你正在戰鬥的敵人的敵方部隊加入部隊行。",
  ["Adds the highest key the player finished this season next to the score."] = "在評分旁新增該玩家本賽季完成的最高鑰石。",
  ["Adds the leader's best timed key level in that dungeon next to the score."] = "在評分旁新增隊長在該地城的最佳限時鑰石層數。",
  ["Adds the per-second figure to saved segments."] = "為儲存的片段新增每秒數值。",
  ["Adds the player's Mythic+ score, coloured by your M+ score colour setting."] = "新增玩家的傳奇鑰石評分，按你的 M+ 評分顏色設定著色。",
  ["Adds the raid size to the difficulty, such as 25H."] = "在難度中加入團隊規模，例如 25H。",
  ["Adds your equipped trinkets that have a use effect to the item bars."] = "將你裝備的具有使用效果的飾品加入物品條。",
  ["Advanced: macro conditions that show or hide bar 1, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 1 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 10, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 10 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 2, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 2 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 3, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 3 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 4, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 4 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 5, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 5 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 6, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 6 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 7, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 7 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 8, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 8 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Advanced: macro conditions that show or hide bar 9, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高階：顯示或隱藏快捷列 9 的巨集條件，例如 [combat] show; hide。設定後將替代“顯示位置”選項。",
  ["Adventure Guide"] = "冒險指南",
  ["After a boss, sends the top line through Phoenix announcements (where it goes is set on the Announcements page)."] = "首領戰後，透過 Phoenix 通告傳送排名第一的一行（傳送位置在通告頁面設定）。",
  ["After a ready check, prints who was not ready or did not answer."] = "就位確認後，列出誰未就位或未回應。",
  ["After a restore, make the Phoenix Edit Mode layout the active one."] = "恢復後，將 Phoenix 編輯模式佈局設為當前佈局。",
  ["After a run"] = "完成後",
  ["After a talent or specialization change, lists tracked cooldowns that are on none of your action bars."] = "天賦或專精更改後，列出不在任何快捷列上的已追蹤冷卻。",
  ["After an enemy is seen dispelling, shows their dispel with its cooldown. Only dispels the game reports plainly are seen."] = "發現敵人驅散後，顯示其驅散及冷卻。只能看到遊戲明確報告的驅散。",
  ["After an enemy's cast is interrupted, the plate shows \"Interrupted by <name>\" for a moment."] = "敵人施法被打斷後，名條會短暫顯示“被 <名字> 打斷”。",
  ["After-match card"] = "賽後卡片",
  ["Aggro border"] = "仇恨邊框",
  ["Alert again after (s)"] = "再次提醒間隔（秒）",
  ["Alert sound"] = "提醒音效",
  ["Alert toasts"] = "提醒彈窗",
  ["Alerts and toasts"] = "提醒與彈窗",
  ["All tracked quests, only those in progress, or only those ready to turn in."] = "所有追蹤的任務、僅進行中的或僅可交付的。",
  ["Alphabetical, or the order you drag them into (Shift-click the bin button to edit)."] = "按字母順序，或按你拖動的順序（Shift 點選收納按鈕編輯）。",
  ["Also keeps errors from other addons and Blizzard's code in the viewer, on this PC only. They never join Phoenix's reports unless you allow it below."] = "同時在檢視器中保留其他插件和暴雪程式碼的錯誤，僅限本機。除非你在下方允許，否則它們從不加入 Phoenix 的報告。",
  ["Also narrow Blizzard's search: minimum rating"] = "同時縮小暴雪搜尋範圍：最低評分",
  ["Also narrow Blizzard's search: needs my role"] = "同時縮小暴雪搜尋範圍：需要我的職責",
  ["Also prints the rating change in your chat window after each rated match."] = "每場評級比賽後，同時在聊天視窗輸出評級變化。",
  ["Also shows a dot for each boss targeting this member."] = "同時為每個以該成員為目標的首領顯示一個圓點。",
  ["Also shows the addons listed in Blizzard's addon compartment as buttons in the bin."] = "同時將暴雪插件收納欄中的插件作為按鈕顯示在收納框中。",
  ["Alt+click Phoenix UI in the minimap addon menu to show or clear the Cast History test strip."] = "在小地圖插件選單中 Alt+點選 Phoenix UI，顯示或清除 Cast History 測試條。",
  ["Alt+click in the addon menu"] = "在插件選單中 Alt+點選",
  ["Alternate power bar"] = "替代能量條",
  ["Always on the minimap"] = "始終在小地圖上",
  ["Always show me"] = "始終顯示我",
  ["An accent dot on communities with unread messages."] = "有未讀訊息的社群上顯示強調色圓點。",
  ["An accent frame on transmog slots with an unsaved change."] = "有未儲存更改的幻化欄位上顯示強調色邊框。",
  ["An accent glow on Great Vault slots you have unlocked."] = "你已解鎖的巨集偉寶庫欄位上顯示強調色光效。",
  ["An accent line under the open tab."] = "開啟的標籤頁下顯示強調線。",
  ["An accent ring on chosen talents, a dim ring on talents you can still pick."] = "已選天賦顯示強調色圓環，仍可選擇的天賦顯示暗色圓環。",
  ["An essential or utility cooldown that is on one of your shown action bars is left out of these rows, so it appears once."] = "已在你顯示的某個快捷列上的核心或輔助冷卻不會出現在這些行中，因此只顯示一次。",
