  ["Comma-separated blocks in order; empty hides the bar. Use currency:ID for one currency and ldb:Name for a LibDataBroker feed. Blocks: bags, clock, coords, currencies, currency, durability, fps, friends, gold, guild, hearth, honor, ilvl, latency, ldb, location, mail, mplus, prof1, prof2, rep, session, spec, vault, volume, xp."] = "逗號分隔的模組，按順序排列；留空隱藏此條。currency:ID 表示單一貨幣，ldb:Name 表示 LibDataBroker 資料來源。模組：bags, clock, coords, currencies, currency, durability, fps, friends, gold, guild, hearth, honor, ilvl, latency, ldb, location, mail, mplus, prof1, prof2, rep, session, spec, vault, volume, xp。",
  ["Comma-separated percentages (1-99) where thin lines are drawn on the power bar, e.g. 30, 60."] = "逗號分隔的百分比（1-99），在能量條上繪製細線，例如 30, 60。",
