  ["Do not share repeatable quests"] = "不共享可重複任務",
  ["Dock several meter windows together under one Studio mover (Embers dock), or leave them free."] = "將多個統計視窗一起停靠在一個 Studio 移動器下（Embers 停靠），或讓它們自由放置。",
  ["Docked above the group finder: your roles at a glance, with locks on roles your class cannot play."] = "停靠在隊伍查詢器上方：一眼看到你的職責，你的職業無法擔任的職責顯示鎖。",
  ["Docked inside the M+ block or as its own widget (also shown in raid boss fights)."] = "停靠在傳奇鑰石模組中或作為獨立元件（首領戰中也會顯示）。",
  ["Docked panel with Phoenix's sorted list of the groups your filter keeps and the why-hidden line."] = "停靠面板，顯示 Phoenix 對你的篩選保留下來的隊伍的排序列表，以及“為何隱藏”說明行。",
  ["Docked window gap"] = "停靠視窗間隙",
  ["Docks the Mythic+ block at the top of the Phoenix quest tracker, or shows it as its own movable window. When the Phoenix tracker is off it always uses its own window."] = "將傳奇鑰石模組停靠在 Phoenix 任務追蹤器頂部，或作為獨立可移動視窗顯示。Phoenix 追蹤器關閉時始終使用獨立視窗。",
  ["Docks the bar on the minimap edge the bar grows along, or lets you place it with the Studio mover."] = "將此條停靠在其增長方向所沿的小地圖邊緣，或用 Studio 移動器自行放置。",
  ["Does not repeat the exact same announcement within 5 seconds."] = "5 秒內不重複完全相同的通告。",
  ["Double-click a group (in Blizzard's list or Phoenix's) to open its sign-up. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "雙擊隊伍（暴雪列表或 Phoenix 列表中）開啟其報名。暴雪用受保護的程式碼執行此視窗；插件在此協助偶爾會導致“介面行為被阻止”訊息。因你的選擇預設開啟；如果看到該訊息請關閉。",
  ["Double-click a group to sign up"] = "雙擊隊伍報名",
  ["Drag Blizzard windows (character, map, bags, talents and about 50 more) by their title. Ctrl + mouse wheel scales, Shift + right-click resets."] = "拖動暴雪視窗（角色、地圖、揹包、天賦及另外約 50 個）的標題移動。Ctrl + 滑鼠滾輪縮放，Shift + 右鍵重置。",
  ["Drag a scoreboard header onto another to change the column order."] = "將記分板標題拖到另一個標題上以改變列順序。",
  ["Drag scoreboard headers"] = "拖動記分板標題",
  ["Drag the whole selection"] = "拖動整個選擇",
  ["Dragged elements snap to the Studio grid."] = "拖動的元素吸附到 Studio 網格。",
  ["Draw the pixel grid while Studio is open."] = "Studio 開啟時繪製畫素網格。",
  ["Draw the screen's centre lines while Studio is open."] = "Studio 開啟時繪製螢幕中心線。",
  ["Draws a line from each attached element to the element it is attached to while Studio is open."] = "Studio 開啟時，從每個附著元素向其附著目標繪製連線。",
  ["Draws a thin line at the execute percent."] = "在斬殺百分比處繪製細線。",
  ["Draws each button on a Phoenix tile with an icon mask; turn off to keep each addon's own look."] = "將每個按鈕繪製在帶圖示遮罩的 Phoenix 方塊上；關閉則保留各插件自己的外觀。",
  ["Draws the bright moving edge on the cooldown swipe."] = "在冷卻掃過上繪製明亮的移動邊緣。",
  ["Draws the frame of buttons that hold no action."] = "繪製沒有動作的按鈕框。",
  ["Draws the pull, break and key countdown that Raid Tools runs (yours or anyone's in the group)."] = "繪製 Raid Tools 執行的開怪、休息和鑰石倒計時（你或隊伍中任何人的）。",
