  ["Each specialization can keep its own block list for every bar (save one with /pui dbspec save). Specs without a saved set use the normal lists."] = "每個專精可以為每個快捷列保留自己的遮蔽列表（用 /pui dbspec save 儲存）。沒有儲存設定的專精使用普通列表。",
  ["Each specialization can use its own profile. When you change spec, Phoenix switches to that profile (after combat). Content profiles for raid, arena or Mythic+ still apply on top."] = "每個專精可以使用自己的配置檔案。切換專精時，Phoenix 會切換到該配置檔案（戰鬥結束後）。團隊、競技場或傳奇鑰石的內容配置仍會疊加生效。",
  ["Each time you save in Edit Mode, Phoenix keeps a copy of the active layout in this profile; /pui editmode restore puts it back as a layout named Phoenix."] = "每次在編輯模式中儲存時，Phoenix 都會在此配置檔案中保留當前佈局的副本；/pui editmode restore 會將其恢復為名為 Phoenix 的佈局。",
  ["Earned achievements get an accent stripe."] = "已獲得的成就顯示強調色條紋。",
