  ["Ember (portrait, flat bars, thick power), Glass (rounded, thin power, class icon), Blizzard-like or Classic-like. Each part of the look can also be changed on its own below."] = "Ember（頭像、扁平計量條、粗能量條）、Glass（圓角、細能量條、職業圖示）、類暴雪或類經典。外觀的每個部分也可在下方單獨更改。",
