  ["Empty uses \"%s ready\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"%s 就緒\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"%s\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"%s\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
