  ["Empty uses \"+%a %t\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"+%a %t\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"+%a XP\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"+%a 經驗\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"+%s %c\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"+%s %c\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"+%s\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"+%s\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"+%s\". Tokens: %s aura or text, %c count."] = "留空使用 \"+%s\"。標記：%s 光環或文字，%c 計數。",
