  ["Empty uses \"-%a %t\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"-%a %t\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"-%s\". Tokens: %s aura or text, %c count."] = "留空使用 \"-%s\"。標記：%s 光環或文字，%c 計數。",
  ["Empty uses \"-Combat\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"-戰鬥\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"Pet +%a\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"寵物 +%a\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Empty uses \"Pet -%a\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "留空使用 \"寵物 -%a\"。標記：%a 數量，%s 法術或物品，%c 計數，%e 事件，%t 字尾（碾壓、偏斜）。",
  ["Enables /gg (and /pui gg) to say a message in instance, raid or party chat."] = "啟用 /gg（和 /pui gg）在副本、團隊或隊伍聊天中傳送訊息。",
