  ["How amounts are written. Numbers the game hides in combat always use the game's own short format."] = "數量的書寫方式。遊戲在戰鬥中隱藏的數字總是使用遊戲自己的縮寫格式。",
  ["How class icons on friend rows look."] = "好友行上職業圖示的外觀。",
