  ["How large numbers look everywhere in Phoenix (meters, data bars, unit text, combat text)."] = "Phoenix 中所有大數字的顯示方式（統計、資料條、單位文字、戰鬥文字）。",
  ["How lines move."] = "文字的移動方式。",
  ["How long Spark waits to merge repeated hits."] = "Spark 合併重複命中前的等待時間。",
  ["How long a dungeon or raid finder invite stays open, used for the queue-pop countdown everywhere (minimap queue eye, queue popup). Battleground invites use the game's own expiry."] = "地城或團隊查詢器邀請的保留時間，用於所有地方的佇列彈出倒計時（小地圖佇列之眼、佇列彈窗）。戰場邀請使用遊戲自己的過期時間。",
