  ["How many finished fights to keep across reloads (pinned ones are always kept)."] = "過載後保留的已結束戰鬥數（固定的總會保留）。",
  ["How many fit in one row before wrapping (overflow goes to the next row)."] = "換行前一行可容納的數量（超出部分放到下一行）。",
  ["How many frames before a new column (or row) starts. 5 keeps one group per column."] = "開始新列（或新行）前的框架數。5 表示每列一個隊伍。",
