  ["How many matching groups the panel lists."] = "面板列出的匹配隊伍數。",
  ["How many meter windows to show (up to 4). Each one has its own meter type and fight; move them in Studio. Different window sets per raid, Mythic+ or arena come from your content profiles."] = "顯示的統計視窗數（最多 4 個）。每個視窗有自己的統計型別和戰鬥；在 Studio 中移動。團隊、傳奇鑰石或競技場的不同視窗組合來自你的內容配置檔案。",
  ["How many names a chat report lists."] = "聊天報告列出的名字數。",
