  ["How often out-of-range units are re-checked (seconds). Lower reacts faster and costs a little more."] = "重新檢查超出範圍單位的頻率（秒）。越低反應越快，開銷略高。",
  ["How often windows redraw in combat. 0.5 seconds is the fastest; slower saves a little CPU."] = "戰鬥中視窗重繪的頻率。0.5 秒最快；更慢可節省少許 CPU。",
