  ["If you are fighting when the countdown ends, it waits until you are out of combat."] = "倒計時結束時如果你在戰鬥中，會等到脫離戰鬥。",
  ["If your character shares a name with an addon or a system word, it stays visible inside file paths in reports. Addon folder names and client words are already on this list."] = "如果你的角色名與某插件名或系統詞相同，它在報告的檔案路徑中會保持可見。插件資料夾名和客戶端詞彙已在此列表中。",
  ["Ignore my own lines"] = "忽略我自己的行",
