  ["Important or purgeable buffs, right of the plate."] = "重要或可淨化的增益，顯示在名條右側。",
  ["Imported NPC colour packs"] = "已匯入的 NPC 顏色包",
  ["In Mythic raids only the 20 players in groups 1 to 4 are shown; benched players in groups 5 to 8 are left out."] = "史詩團隊副本中只顯示 1 到 4 隊的 20 名玩家；5 到 8 隊的替補不顯示。",
  ["In Mythic+, hide reminders on keys at or above this level (0 never hides)."] = "傳奇鑰石中，在此層數及以上的鑰石隱藏提醒（0 從不隱藏）。",
  ["In Mythic+, how much enemy forces an enemy is worth (data from the M+ tracker)."] = "傳奇鑰石中，一個敵人值多少敵方部隊（資料來自傳奇鑰石追蹤器）。",
  ["In Mythic+, shows how much enemy forces each enemy is worth, next to its plate."] = "傳奇鑰石中，在名條旁顯示每個敵人值多少敵方部隊。",
  ["In arenas and battlegrounds Tab targets the nearest enemy player (an override binding; your own Tab comes back outside)."] = "在競技場和戰場中，Tab 選中最近的敵方玩家（覆蓋繫結；離開後恢復你自己的 Tab）。",
  ["In arenas, a coloured dot for each enemy that is targeting this member (the same colours as your arena frames)."] = "在競技場中，每個以該成員為目標的敵人顯示一個彩色圓點（與競技場框架顏色相同）。",
  ["In category and list views, shows one empty slot with the free count instead of every empty slot."] = "在分類和列表檢視中，只顯示一個帶空格數的空格子，而不是每個空格子。",
  ["In combat, colour enemy plates by your threat. Tanks want aggro; everyone else wants none."] = "戰鬥中按你的仇恨為敵方名條著色。坦克想要仇恨；其他人都不想要。",
  ["In game only"] = "僅遊戲內",
