  ["Invites friends, Battle.net friends and guild members who whisper one of your words. Never strangers; never during chat lockdown."] = "邀請密語你某個關鍵詞的好友、Battle.net好友和公會成員。從不邀請陌生人；聊天鎖定期間從不邀請。",
  ["Item IDs shown in the Pinned category and never sold as junk. Use Pin mode in the bags to add items by clicking."] = "顯示在“固定”分類中且從不作為垃圾出售的物品 ID。在揹包中使用固定模式可點選新增物品。",
  ["Item IDs shown on the Action Bars item bar and the Cooldown Manager custom bar, in order (for example Healthstone 5512, healing potions, quest items, toys)."] = "按順序顯示在快捷列物品條和冷卻管理器自訂條上的物品 ID（例如治療石 5512、治療藥水、任務物品、玩具）。",
  ["Item IDs that say when they are ready again (Healthstone is 5512). Potions you add here work the same."] = "就緒時提示的物品 ID（治療石是 5512）。新增到這裡的藥水同樣有效。",
  ["Item IDs treated as junk. Use Junk mode in the bags to add items by clicking."] = "視為垃圾的物品 ID。在揹包中使用垃圾模式可點選新增物品。",
