  ["Item reference, comparison, embedded and battle pet tooltips (Phoenix HUD Tooltip owns the main tooltip)."] = "物品連結、比較、嵌入和戰鬥寵物滑鼠提示（主滑鼠提示由 Phoenix HUD Tooltip 管理）。",
