  ["Join and leave lines are collected for this long before the summary is printed."] = "進入和離開的行會收集這麼長時間後再輸出摘要。",
  ["Junk overlay"] = "垃圾覆蓋",
  ["Keep Blizzard's buttons, or use Phoenix's matching set (Blizzard's are faded out, never moved)."] = "保留暴雪按鈕，或使用 Phoenix 對應的一套（暴雪的被淡化，從不移動）。",
  ["Keep after the fight (s)"] = "戰鬥後保留（秒）",
