  ["Keep only boss fights in the saved segments."] = "儲存的片段中只保留首領戰。",
  ["Keep stats for this character only, or one set for all your characters."] = "只為此角色儲存統計，或為所有角色儲存一份。",
  ["Keeps a list of each character's bag and bank items so you can see them from any character (Bank > Alts)."] = "儲存每個角色的揹包和銀行物品列表，以便在任何角色上檢視（銀行 > 小號）。",
