  ["Notifications: text size"] = "通知：文字大小",
  ["Notifications: time on screen (s)"] = "通知：螢幕停留時間（秒）",
  ["Number font"] = "數字字型",
  ["Number format"] = "數字格式",
  ["Number of icons"] = "圖示數量",
  ["Number style"] = "數字樣式",
  ["Numbers follow FrameSort"] = "編號跟隨 FrameSort",
  ["Objective progress sound"] = "目標進度音效",
  ["Objective tracker"] = "目標追蹤器",
  ["Objectives go from red to green as their count fills."] = "目標隨計數填滿從紅色變為綠色。",
  ["Off while a boss mod keeps stats"] = "首領插件記錄統計時關閉",
  ["Off-tank colour"] = "副坦顏色",
  ["Off: the All filter lists only Blizzard elements you changed; the Blizzard filter always lists them all."] = "關閉：“全部”篩選只列出你更改過的暴雪元素；“暴雪”篩選始終列出全部。",
  ["On a boss, shows your best saved pull on the same boss and difficulty in the title, and after the pull how you did against it."] = "在首領戰中，標題顯示你在同一首領和難度上儲存的最佳拉怪，拉怪後顯示你與其的對比。",
  ["On: the full log goes to the dashboard, other addons' errors included, so conflicts with Phoenix can be found (same privacy filters: names and paths scrubbed). Off: only Phoenix's own errors leave this PC."] = "開啟：完整日誌（包括其他插件的錯誤）傳送到儀表板，以便找出與 Phoenix 的衝突（相同的隱私過濾：名字和路徑已清除）。關閉：只有 Phoenix 自己的錯誤離開本機。",
  ["One NPC per line: its NPC id or exact name, a colour, then optionally a size and 'glow'. Examples: 185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow. The first line for an NPC wins. In some restricted content the game hides NPC ids and names; then a rule waits until they are visible."] = "每行一個 NPC：其 NPC ID 或準確名稱、顏色，然後可選大小和 'glow'。示例：185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow。同一 NPC 以第一行為準。在某些受限內容中游戲會隱藏 NPC ID 和名稱；此時規則會等到它們可見。",
  ["One binding per row. Pick a modifier, a mouse button or a key, and what it does: target, menu, focus, assist, cast a spell, run a macro or use an item. Keys work while the mouse is over a frame. Each spec can keep its own list (Editing as). Changes made in combat apply as soon as combat ends."] = "每行一個繫結。選擇修飾鍵、滑鼠按鍵或按鍵，以及其作用：目標、選單、專注目標、協助、施放法術、執行巨集或使用物品。滑鼠在框架上時按鍵生效。每個專精可保留自己的列表（編輯物件）。戰鬥中的更改在戰鬥結束後立即生效。",
  ["One button per line: bar.button: options. Options: nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash. Example: 1.12:nohotkey,alpha=0.6"] = "每行一個按鈕：bar.button: options。選項：nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash。示例：1.12:nohotkey,alpha=0.6",
  ["One colour for every glow: the theme's accent. Off keeps each glow's own colour."] = "所有光效使用一種顏色：主題強調色。關閉則保留每個光效自己的顏色。",
  ["One font everywhere"] = "全域性統一字型",
  ["One large icon in the middle for a big personal or external defensive."] = "中間一個大圖示，顯示大型個人或外部減傷。",
  ["One line each time your pet becomes unhappy."] = "寵物每次變得不高興時輸出一行。",
  ["One line each: \"Boss name: text\". Lines starting with \"*:\" show for every boss."] = "每行一條：\"首領名: 文字\"。以 \"*:\" 開頭的行對所有首領顯示。",
  ["One line each: \"Original name = New text\". Blank new text hides the name."] = "每行一條：\"原名稱 = 新文字\"。新文字留空則隱藏名稱。",
  ["One line each: \"spellID: sound\" (a Phoenix or shared sound name), optionally \", removed\" or \", stacks\". The game plays it itself, so it works for private boss debuffs too."] = "每行一條：\"spellID: sound\"（Phoenix 或共享音效名），可選 \", removed\" 或 \", stacks\"。由遊戲自己播放，因此對首領私有減益也有效。",
  ["One line per boss, by name or encounter ID: \"off\" hides Pulse bars, \"bars=4\" limits bars, \"hud=on\" or \"hud=off\" for the next-abilities list. Example: Dimensius: bars=4 hud=on"] = "每個首領一行，按名稱或首領戰 ID：\"off\" 隱藏 Pulse 計時條，\"bars=4\" 限制計時條數，\"hud=on\" 或 \"hud=off\" 控制接下來的技能列表。示例：Dimensius: bars=4 hud=on",
  ["One line per click: \"1: target\", \"2: focus\", \"shift-1: spell:Polymorph\", \"ctrl-3: macro:/cast [@arena1] Kick\", \"3: none\". Applied when you leave combat."] = "每次點選一行：\"1: target\"、\"2: focus\"、\"shift-1: spell:Polymorph\"、\"ctrl-3: macro:/cast [@arena1] Kick\"、\"3: none\"。脫離戰鬥時生效。",
  ["One line per reminder: key: sound=SoundName icon=IconID (for example 'oil: sound=Phoenix icon=463543'). Keys: intellect, stamina, lethal, pet, oil, talents, custom12345 ..."] = "每個提醒一行：key: sound=SoundName icon=IconID（例如 'oil: sound=Phoenix icon=463543'）。鍵：intellect, stamina, lethal, pet, oil, talents, custom12345 ...",
  ["One line per spec: spec ID = roles, e.g. '105 = HEALER, DPS'. Used when Roles per spec is 'My own list'."] = "每個專精一行：專精 ID = 職責，例如 '105 = HEALER, DPS'。在“每個專精的職責”為“我的列表”時使用。",
  ["One per line as itemID=Category (a built-in id such as consumables, or the name of one of your rules)."] = "每行一個，格式 itemID=分類（內建 ID，如 consumables，或你某條規則的名稱）。",
  ["One per line: a spell ID, optionally followed by :name (for example 1234:Flask). Shows when you lack that buff."] = "每行一個：法術 ID，可選後跟 :名稱（例如 1234:Flask）。缺少該增益時顯示。",
  ["One search across friends, guild and recent players, with sort and actions, beside the friends list."] = "在好友列表旁，一次搜尋好友、公會和最近遇到的玩家，帶排序和操作。",
  ["One section per addon (collapsible, with counts, first and last seen and the session), or a single newest-first list."] = "每個插件一個分割槽（可摺疊，帶計數、首次和最近出現時間及會話），或單一的最新優先列表。",
  ["One setting for every place roles are set: manual, the role your spec plays, or your own list below. Auto stands down while BigWigs sets roles."] = "所有設定職責的地方共用一個設定：手動、你專精擔任的職責或你下方的列表。BigWigs 設定職責時“自動”會讓位。",
  ["One switch for every chat announcement Phoenix modules can make. Modules only pick what to say; where it goes is set here."] = "Phoenix 模組所有聊天通告的總開關。模組只決定說什麼；傳送到哪裡在此設定。",
  ["Online friends count on the minimap; hover it for the list."] = "小地圖上的線上好友數；懸停檢視列表。",
  ["Online friends' names in their class colour."] = "線上好友名字使用職業顏色。",
  ["Only DR I can trigger"] = "僅我能觸發的遞減",
  ["Only cooldowns longer than (s)"] = "僅冷卻長於（秒）",
  ["Only debuffs your class and spec can remove, or any dispellable debuff (useful to call for help)."] = "僅你的職業和專精能移除的減益，或任何可驅散減益（便於呼叫幫助）。",
  ["Only in combat"] = "僅戰鬥中",
  ["Only online players in the search panel."] = "搜尋面板中只顯示線上玩家。",
  ["Only tanks and healers get a role marker."] = "只有坦克和治療顯示職責標記。",
  ["Opacity"] = "不透明度",
  ["Opacity of a frame whose unit is out of range."] = "單位超出範圍時框架的不透明度。",
  ["Opacity of bar 1 while faded."] = "快捷列 1 淡出時的不透明度。",
  ["Opacity of bar 10 while faded."] = "快捷列 10 淡出時的不透明度。",
  ["Opacity of bar 2 while faded."] = "快捷列 2 淡出時的不透明度。",
  ["Opacity of bar 3 while faded."] = "快捷列 3 淡出時的不透明度。",
  ["Opacity of bar 4 while faded."] = "快捷列 4 淡出時的不透明度。",
  ["Opacity of bar 5 while faded."] = "快捷列 5 淡出時的不透明度。",
  ["Opacity of bar 6 while faded."] = "快捷列 6 淡出時的不透明度。",
  ["Opacity of bar 7 while faded."] = "快捷列 7 淡出時的不透明度。",
  ["Opacity of bar 8 while faded."] = "快捷列 8 淡出時的不透明度。",
  ["Opacity of bar 9 while faded."] = "快捷列 9 淡出時的不透明度。",
  ["Opacity of out-of-range frames."] = "超出範圍框架的不透明度。",
  ["Opacity of plates that are not your target while you have one; 1 keeps them fully visible."] = "你有目標時非目標名條的不透明度；1 保持完全可見。",
  ["Opacity of the bars."] = "計量條的不透明度。",
  ["Opacity of the chat panel."] = "聊天面板的不透明度。",
  ["Opacity of the dark background behind Phoenix bars."] = "Phoenix 計量條後深色背景的不透明度。",
  ["Opacity of the empty part of each bar."] = "每個計量條空白部分的不透明度。",
  ["Opacity of the health fill."] = "生命填充的不透明度。",
  ["Opacity of the item bar while faded."] = "物品條淡出時的不透明度。",
  ["Opacity of the pet bar while faded."] = "寵物條淡出時的不透明度。",
  ["Opacity of the stance bar while faded."] = "姿態條淡出時的不透明度。",
  ["Opacity of the text."] = "文字的不透明度。",
  ["Opacity of the vehicle exit button while faded."] = "離開載具按鈕淡出時的不透明度。",
  ["Opacity of the whole tracker."] = "整個追蹤器的不透明度。",
  ["Opacity out of combat"] = "非戰鬥不透明度",
  ["Opacity used when the where-to-show rule hides the frame (0 = invisible, higher = faded)."] = "“顯示位置”規則隱藏框架時使用的不透明度（0 = 不可見，更高 = 淡化）。",
  ["Opacity used when the where-to-show rule hides the frames (0 = invisible). They stay clickable in combat because the game locks that."] = "“顯示位置”規則隱藏框架時使用的不透明度（0 = 不可見）。由於遊戲鎖定，戰鬥中它們仍可點選。",
  ["Open Phoenix Studio button"] = "開啟 Phoenix Studio 按鈕",
  ["Open a blocked report in the copy box"] = "在複製框中開啟被阻止的報告",
  ["Open containers"] = "開啟容器",
  ["Open key"] = "開啟按鍵",
  ["Open recap when I die"] = "我死亡時開啟死亡回顧",
  ["Open the bin by"] = "開啟收納框的方式",
  ["Open the scoreboard after a battleground"] = "戰場結束後開啟記分板",
  ["Open the viewer on a new error"] = "新錯誤時開啟檢視器",
  ["Opens Phoenix's scoreboard when a battleground ends."] = "戰場結束時開啟 Phoenix 記分板。",
  ["Opens at"] = "開啟於",
  ["Opens beside Blizzard's PvP window, or only with /pui pvp card."] = "在暴雪 PvP 視窗旁開啟，或僅透過 /pui pvp card 開啟。",
  ["Opens lootable bag items (caches, satchels) one at a time out of combat. Hold Shift to keep them closed."] = "非戰鬥時逐個開啟揹包中可拾取的物品（寶箱、揹包）。按住 Shift 保持不開啟。",
  ["Opens the error viewer by itself. Never during combat: it waits until the fight ends."] = "自動開啟錯誤檢視器。戰鬥中從不開啟：等到戰鬥結束。",
  ["Opens your death recap automatically when you die."] = "你死亡時自動開啟死亡回顧。",
  ["Optional: the season's achievement ID, so the count comes from the game. 0 = automatic (Gladiator) or Phoenix's count."] = "可選：賽季成就 ID，使計數來自遊戲。0 = 自動（角鬥士）或 Phoenix 計數。",
  ["Options mode"] = "選項模式",
  ["Oracle"] = "Oracle",
  ["Oracle search"] = "Oracle 搜尋",
  ["Order of Phoenix's list, e.g. 'mprating desc, age asc'. Empty keeps Blizzard's order."] = "Phoenix 列表的排序，例如 'mprating desc, age asc'。留空保留暴雪順序。",
  ["Order of categories, highest first. Words: cc, defensive, important. Leave one out to never show it (\"cc\" alone shows only crowd control)."] = "分類順序，最高優先。關鍵詞：cc, defensive, important。省略某項則從不顯示（單獨 \"cc\" 只顯示控制）。",
  ["Order of the party frames."] = "隊伍框架的順序。",
  ["Order of the search panel."] = "搜尋面板的順序。",
  ["Order raid frames by group, by role (in the role order below), by class or by name."] = "按隊伍、職責（按下方職責順序）、職業或名字排序團隊框架。",
  ["Order used when sorting by role (raid and party)."] = "按職責排序時使用的順序（團隊和隊伍）。",
  ["Other plates' opacity"] = "其他名條的不透明度",
  ["Other players' item level and specialization (asked from the server once, then remembered for 5 minutes; never in combat)."] = "其他玩家的物品等級和專精（向伺服器詢問一次，之後記住 5 分鐘；戰鬥中從不詢問）。",
  ["Other tooltips"] = "其他滑鼠提示",
  ["Out of range"] = "超出範圍",
  ["Out of range colour"] = "超出範圍顏色",
  ["Out of range opacity"] = "超出範圍不透明度",
  ["Out of sight flash time"] = "視線外閃爍時間",
  ["Out-of-range opacity"] = "超出範圍不透明度",
  ["Outgoing hits"] = "輸出命中",
  ["Outgoing: animation"] = "輸出：動畫",
  ["Outgoing: direction"] = "輸出：方向",
  ["Outgoing: most lines per second"] = "輸出：每秒最多行數",
  ["Outgoing: on"] = "輸出：開啟",
  ["Outgoing: opacity"] = "輸出：不透明度",
  ["Outgoing: scroll height"] = "輸出：滾動高度",
  ["Outgoing: text align"] = "輸出：文字對齊",
  ["Outgoing: text size"] = "輸出：文字大小",
  ["Outgoing: time on screen (s)"] = "輸出：螢幕停留時間（秒）",
  ["Outline around chat text."] = "聊天文字的描邊。",
  ["Outline around combat text."] = "戰鬥文字的描邊。",
  ["Outline for the texts with a size set here."] = "在此設定了大小的文字的描邊。",
  ["Outline on Phoenix window and label text."] = "Phoenix 視窗和標籤文字的描邊。",
  ["Outline or shadow behind unit-frame text."] = "單位框架文字後的描邊或陰影。",
  ["Outlines casts the game marks as important (big hits, heals, crowd control)."] = "為遊戲標記為重要的施法描邊（高傷害、治療、控制）。",
  ["Outlines the button that holds the spell the game's rotation helper suggests next."] = "為遊戲輸出迴圈助手建議的下一個法術所在按鈕描邊。",
  ["Outlines your focus target's plate."] = "為你專注目標的目標名條描邊。",
  ["Overall opacity of bar 1."] = "快捷列 1 的整體不透明度。",
  ["Overall opacity of bar 10."] = "快捷列 10 的整體不透明度。",
  ["Overall opacity of bar 2."] = "快捷列 2 的整體不透明度。",
