  ["Overall opacity of bar 4."] = "快捷列 4 的整體不透明度。",
  ["Overall opacity of bar 5."] = "快捷列 5 的整體不透明度。",
  ["Overall opacity of bar 6."] = "快捷列 6 的整體不透明度。",
