  ["Overflow marks"] = "溢位標記",
  ["Overlay darkness"] = "疊加層暗度",
  ["Override bar"] = "覆蓋快捷列",
  ["Overrides for single instances: 'instance ID:option=on' or '=off'. An instance without a line follows its content type. Inside an instance, /pui quiet here <option> on|off|inherit adds or removes a line."] = "單個副本的覆蓋設定：'instance ID:option=on' 或 '=off'。沒有對應行的副本跟隨其內容型別。在副本內，/pui quiet here <option> on|off|inherit 會新增或移除一行。",
  ["Pace for"] = "節奏對比",
  ["Pace line"] = "節奏線",
  ["Pages shown at the top of the sidebar, in this order."] = "側邊欄頂部按此順序顯示的頁面。",
  ["Pain bar colour"] = "痛苦條顏色",
