  ["Party: you"] = "隊伍：你",
  ["Paste a Phoenix pack string (PUIPACK1|name|instance|rules). Then add its name, shown on the row, to Rule packs in use. A pack with an instance id works only inside that dungeon or raid."] = "貼上 Phoenix 包字串（PUIPACK1|name|instance|rules）。然後將行上顯示的名稱加入“使用中的規則包”。帶副本 ID 的包只在該地城或團隊副本內生效。",
  ["Pause key"] = "暫停按鍵",
