  ["Percentages where thin lines are drawn on each buff bar (for example 30 for the pandemic window)."] = "在每個增益條上繪製細線的百分比（例如 30 表示傳染視窗）。",
  ["Performance sampler"] = "效能取樣器",
  ["Personal health, power, class resource, cast, global cooldown and totem bars."] = "個人生命、能量、職業資源、施法、公共冷卻和圖騰條。",
