  ["Pets, guardians and other summons controlled by players get a smaller plate."] = "玩家控制的寵物、守護者和其他召喚物使用較小的名條。",
  ["Phoenix action bars hide while a controller is active, for controller addons that bring their own bars."] = "手柄啟用時隱藏 Phoenix 快捷列，適用於自帶快捷列的手柄插件。",
  ["Phoenix action bars hide while you are inside a player house and come back when you leave."] = "你在玩家房屋內時隱藏 Phoenix 快捷列，離開後恢復。",
  ["Phoenix action bars with paging, where-to-show rules, mouse-over fade, keybind mode, cooldowns, range colouring and proc glow, plus stance, pet, vehicle exit and item bars."] = "Phoenix 快捷列：翻頁、顯示位置規則、懸停淡出、按鍵繫結模式、冷卻、範圍著色和觸發光效，另有姿態條、寵物條、離開載具按鈕和物品條。",
  ["Phoenix background and border on tooltips; off keeps Blizzard's look."] = "滑鼠提示使用 Phoenix 背景和邊框；關閉保留暴雪外觀。",
  ["Phoenix bank window"] = "Phoenix 銀行視窗",
  ["Phoenix bars and names use the class colours below instead of the game's."] = "Phoenix 計量條和名字使用下方的職業顏色而不是遊戲的。",
  ["Phoenix bars for breath, fatigue and feign death timers."] = "Phoenix 的呼吸、疲勞和假死計時條。",
  ["Phoenix border and tabs"] = "Phoenix 邊框和標籤",
  ["Phoenix boxes; the check mark takes the accent colour."] = "Phoenix 核取方塊；勾號使用強調色。",
  ["Phoenix builds this many plates out of combat so big pulls never build frames mid-fight."] = "Phoenix 在非戰鬥時預先建立這麼多名條，大規模拉怪時就不會在戰鬥中建立框架。",
  ["Phoenix button face on Blizzard panel buttons."] = "暴雪面板按鈕使用 Phoenix 按鈕外觀。",
  ["Phoenix chat bubbles in the open world (Blizzard locks them inside instances)."] = "野外使用 Phoenix 聊天氣泡（暴雪在副本內鎖定它們）。",
  ["Phoenix draws this frame, Blizzard shows the default frame, or hidden shows neither."] = "由 Phoenix 繪製此框架、暴雪顯示預設框架，或隱藏兩者。",
  ["Phoenix draws your buffs and debuffs in two movable rows, or Blizzard's default buff frame stays."] = "Phoenix 在兩行可移動的位置繪製你的增益和減益，或保留暴雪預設增益框架。",
  ["Phoenix dropdown boxes with an accent arrow."] = "帶強調色箭頭的 Phoenix 下拉框。",
  ["Phoenix ember backdrop behind mount and pet models."] = "坐騎和寵物模型後的 Phoenix 餘燼背景。",
  ["Phoenix ember backdrop behind the character model."] = "角色模型後的 Phoenix 餘燼背景。",
  ["Phoenix emoji art"] = "Phoenix 表情圖",
  ["Phoenix error reports go to the vq8s.com dashboard through the Companion app (and the export string works). See exactly what leaves this PC with Preview on the error reporter. Nothing is shared while off."] = "Phoenix 錯誤報告透過 Companion 應用傳送到 vq8s.com 儀表板（匯出字串也可用）。在錯誤報告器中使用“預覽”可準確檢視離開本機的內容。關閉時不共享任何內容。",
  ["Phoenix font on cinematic subtitles."] = "過場動畫字幕使用 Phoenix 字型。",
  ["Phoenix fonts and bars on top-centre and minimap widgets and the encounter power bar."] = "頂部中央和小地圖元件以及首領戰能量條使用 Phoenix 字型和計量條。",
  ["Phoenix fonts on raid warnings, boss emotes and the red error text."] = "團隊警告、首領表情和紅色錯誤文字使用 Phoenix 字型。",
  ["Phoenix frame skin for Details! windows when that addon is installed."] = "安裝 Details! 時為其視窗應用 Phoenix 框架美化。",
  ["Phoenix frame skin for Pawn when that addon is installed."] = "安裝 Pawn 時為其應用 Phoenix 框架美化。",
  ["Phoenix frame skin for Plater options when that addon is installed."] = "安裝 Plater 時為其選項應用 Phoenix 框架美化。",
  ["Phoenix frame skin for WeakAuras options when that addon is installed."] = "安裝 WeakAuras 時為其選項應用 Phoenix 框架美化。",
  ["Phoenix input boxes with a hairline border."] = "帶細線邊框的 Phoenix 輸入框。",
  ["Phoenix keybinds"] = "Phoenix 按鍵繫結",
  ["Phoenix look for Blizzard's windows, menus, tooltips and popups (their own layout and features, your theme), and Details!, Pawn, WeakAuras and Plater; each has its own switch."] = "為暴雪的視窗、選單、滑鼠提示和彈窗（保持其佈局和功能，套用你的主題）以及 Details!、Pawn、WeakAuras 和 Plater 提供 Phoenix 外觀；每項都有自己的開關。",
  ["Phoenix look for every context menu and dropdown list, including the damage meter's."] = "為所有右鍵選單和下拉選單（包括傷害統計的）提供 Phoenix 外觀。",
  ["Phoenix look on Blizzard's meter"] = "暴雪統計使用 Phoenix 外觀",
  ["Phoenix look on flyouts"] = "彈出欄使用 Phoenix 外觀",
  ["Phoenix minimap: shape, border, texts, coordinates, queue countdown, addon button bin and more."] = "Phoenix 小地圖：形狀、邊框、文字、座標、佇列倒計時、插件按鈕收納框等。",
  ["Phoenix nameplates: enemy and friendly styles, threat and NPC colours, cast bars with your interrupt, aura lanes, target and focus highlights, quest, execute and Mythic+ forces indicators."] = "Phoenix 名條：敵方和友方樣式、仇恨和 NPC 顏色、帶你打斷的施法條、光環通道、目標和專注目標高亮、任務、斬殺和傳奇鑰石部隊指示。",
  ["Phoenix only restyles the cooldown icons and bars; their places, sizes and which ones show stay as Blizzard's Cooldown Manager sets them (from the game's next layout pass). The safest mode for testing."] = "Phoenix 只重新美化冷卻圖示和計量條；它們的位置、大小和顯示哪些仍由暴雪冷卻管理器設定（從遊戲下一次佈局起）。測試時最安全的模式。",
  ["Phoenix panel"] = "Phoenix 面板",
  ["Phoenix panel on Blizzard's tutorial help tips."] = "暴雪教程幫助提示使用 Phoenix 面板。",
  ["Phoenix party and raid frames: layouts by group size, sorting, role icons, dispel highlight, aura icons, corner indicators, private auras, heal prediction, range fade and a test mode."] = "Phoenix 隊伍和團隊框架：按隊伍規模的佈局、排序、職責圖示、驅散高亮、光環圖示、角落指示器、私有光環、治療預測、範圍淡化和測試模式。",
  ["Phoenix pet bar (hides the Blizzard one)."] = "Phoenix 寵物條（隱藏暴雪的）。",
  ["Phoenix player, target, focus, pet, target-of-target, focus-target and boss frames, and your buff and debuff rows."] = "Phoenix 玩家、目標、專注目標、寵物、目標的目標、專注目標和首領框架，以及你的增益和減益行。",
  ["Phoenix positions the game's buff bars in its own rows; off leaves them to the game."] = "Phoenix 將遊戲的增益條放入自己的行中；關閉則交給遊戲。",
  ["Phoenix positions the game's buff icons in its own rows; off leaves them to the game."] = "Phoenix 將遊戲的增益圖示放入自己的行中；關閉則交給遊戲。",
  ["Phoenix positions the game's essential cooldowns in its own rows; off leaves them to the game."] = "Phoenix 將遊戲的核心冷卻放入自己的行中；關閉則交給遊戲。",
  ["Phoenix positions the game's utility cooldowns in its own rows; off leaves them to the game."] = "Phoenix 將遊戲的輔助冷卻放入自己的行中；關閉則交給遊戲。",
