  ["Phoenix's look on Blizzard's friends list (through hooks; Blizzard still builds the list)."] = "暴雪好友列表上的 Phoenix 外觀（透過鉤子；列表仍由暴雪構建）。",
  ["Phoenix's look on the friends list, zone and activity per friend, one search across friends, guild and recent players, and invite accept per source (off)."] = "好友列表的 Phoenix 外觀、每位好友的區域和活動、跨好友、公會和最近玩家的統一搜尋，以及按來源接受邀請（關閉）。",
  ["Phoenix, Glass, Blizzard-like, compact or text-only rows. Every part of a look can also be changed below."] = "Phoenix、Glass、類暴雪、緊湊或純文字行。外觀的每個部分也可在下方更改。",
