  ["Scroll rows with the mouse wheel"] = "用滑鼠滾輪滾動行",
  ["Scrolling combat text in four areas, combat in and out, item ready, loot, money, reputation and XP. Turns Blizzard's combat text off while on."] = "四個區域的滾動戰鬥文字：進入和離開戰鬥、物品就緒、拾取、金錢、聲望和經驗。開啟時關閉暴雪的戰鬥文字。",
