  ["Seconds before the popup closes after the mouse leaves."] = "滑鼠離開後彈窗關閉前的秒數。",
  ["Seconds left until the DR resets, written by the game."] = "遞減重置前剩餘的秒數，由遊戲提供。",
  ["Seconds the finished or interrupted cast stays visible while fading (0 hides it at once)."] = "完成或被打斷的施法在淡出時保持可見的秒數（0 立即隱藏）。",
  ["Sections start collapsed"] = "分割槽預設摺疊",
  ["Sell junk automatically"] = "自動出售垃圾",
  ["Sells grey items and items you marked as junk when you open a vendor. Off at first install; the Sell junk button works either way."] = "開啟商人時出售灰色物品和你標記為垃圾的物品。首次安裝時關閉；“出售垃圾”按鈕總是可用。",
  ["Sells grey items when you open a vendor. While Vault is on, Vault's own junk setting decides instead."] = "開啟商人時出售灰色物品。Vault 開啟時，改由 Vault 自己的垃圾設定決定。",
  ["Sends each installed addon's folder name, version and whether it is enabled, so the dashboard can rank possible conflicts. Nothing else about your addons or character."] = "傳送每個已安裝插件的資料夾名、版本和是否啟用，以便儀表板排查可能的衝突。不會傳送關於你的插件或角色的其他內容。",
  ["Sends objective progress and completions through Phoenix announcements (the Quest topic there decides where)."] = "透過 Phoenix 通告傳送目標進度和完成情況（由那裡的“任務”主題決定傳送位置）。",
  ["Sends the break through the announcement router (where it goes is set on the Announcements page; off until you turn it on there)."] = "透過通告路由傳送休息（傳送位置在“通告”頁面設定；在那裡開啟前為關閉）。",
  ["Sends your key to group members who also use Phoenix, so /keys can list theirs."] = "將你的鑰石傳送給同樣使用 Phoenix 的隊友，以便 /keys 列出他們的鑰石。",
  ["Sentinel notice"] = "Sentinel 通知",
  ["Separators between blocks"] = "模組之間的分隔線",
  ["Server time"] = "伺服器時間",
  ["Set items (such as tier) show how many pieces of that set you are wearing."] = "套裝物品（例如套裝）顯示你穿戴了該套裝的幾件。",
  ["Set pieces equipped"] = "已穿戴的套裝件數",
  ["Settings"] = "設定",
  ["Settings profile used by this character. Switching applies every setting immediately."] = "此角色使用的設定配置檔案。切換後立即應用所有設定。",
  ["Shade the screen edges and the centre area where your character stands, to keep frames out of the way."] = "為螢幕邊緣和角色所在的中央區域加陰影，讓框架避開這些區域。",
  ["Shades the end of your cast that falls inside your network latency, so you can queue the next spell there."] = "為施法末尾處於網路延遲內的部分加陰影，你可以在此時排隊下一個法術。",
  ["Shadowsight timer"] = "暗影視界計時",
  ["Shaman colour"] = "薩滿祭司顏色",
  ["Shape of action-button and cooldown icons: square, rounded, circle, hexagon and more (Phoenix masks)."] = "動作按鈕和冷卻圖示的形狀：方形、圓角、圓形、六邊形等（Phoenix 遮罩）。",
  ["Share accepted quests"] = "共享接受的任務",
  ["Share my key with my group"] = "與隊伍共享我的鑰石",
