  ["Shorten names longer than"] = "縮短長於此的名字",
  ["Shortens key names so they fit: SHIFT-1 becomes S1, mouse button 4 becomes M4, mouse wheel up becomes WU."] = "縮短按鍵名稱以便放下：SHIFT-1 變為 S1，滑鼠按鍵 4 變為 M4，滾輪向上變為 WU。",
