  ["Show absorbs"] = "顯示吸收",
  ["Show bar 1 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 1。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
