  ["Show bar 4 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 4。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
  ["Show bar 5 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 5。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
  ["Show bar 6 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 6。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
  ["Show bar 7 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 7。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
  ["Show bar 8 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 8。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
  ["Show bar 9 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示快捷列 9。戰鬥、載具、寵物對戰、坐騎和馭空術即使在戰鬥中也立即生效。",
  ["Show empty buttons"] = "顯示空按鈕",
