  ["Show names"] = "顯示名字",
  ["Show only friends playing World of Warcraft: others are left out of the Phoenix list and dimmed on Blizzard's list (the game has no such filter of its own)."] = "只顯示正在玩魔獸世界的好友：其他人不在 Phoenix 列表中，並在暴雪列表中變暗（遊戲本身沒有此過濾）。",
  ["Show or collapse each built-in category (Pinned, New, Keystone shelf, Equipment sets, Junk and the rest)."] = "顯示或摺疊每個內建分類（固定、新物品、鑰石架、裝備方案、垃圾等）。",
  ["Show or hide tooltips while you are in combat."] = "在戰鬥中顯示或隱藏滑鼠提示。",
  ["Show party frames when solo"] = "單人時顯示隊伍框架",
  ["Show realm time instead of your computer's time."] = "顯示伺服器時間而不是電腦時間。",
  ["Show tenths of a second on the timer."] = "計時器顯示十分之一秒。",
  ["Show the age of your oldest application"] = "顯示你最早申請的時長",
  ["Show the boss frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示首領框架。下面一行解釋它當前為何隱藏。",
  ["Show the focus frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示專注目標框架。下面一行解釋它當前為何隱藏。",
  ["Show the focus target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示專注目標框架。下面一行解釋它當前為何隱藏。",
  ["Show the gap to the nearest element on each side of the selected one."] = "顯示所選元素各邊與最近元素的間距。",
  ["Show the party frames everywhere, never, or only in the content, combat state and group you pick. The line below explains why they are hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示隊伍框架。下面一行解釋它們當前為何隱藏。",
  ["Show the pet frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示寵物框架。下面一行解釋它當前為何隱藏。",
  ["Show the player frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示玩家框架。下面一行解釋它當前為何隱藏。",
  ["Show the raid frames everywhere, never, or only in the content, combat state and group you pick. The line below explains why they are hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示團隊框架。下面一行解釋它們當前為何隱藏。",
  ["Show the rated card"] = "顯示評級卡片",
  ["Show the ring only while you are in combat."] = "僅在戰鬥中顯示環。",
  ["Show the target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示目標框架。下面一行解釋它當前為何隱藏。",
  ["Show the target of target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、從不或僅在你選擇的內容、戰鬥狀態和隊伍中顯示目標的目標框架。下面一行解釋它當前為何隱藏。",
  ["Show who interrupted a cast"] = "顯示誰打斷了施法",
  ["Show yourself in party"] = "在隊伍中顯示自己",
  ["Show/hide all windows key"] = "顯示/隱藏所有視窗按鍵",
  ["Show: Arena 1"] = "顯示：競技場 1",
  ["Show: Arena 2"] = "顯示：競技場 2",
  ["Show: Arena 3"] = "顯示：競技場 3",
  ["Show: Focus"] = "顯示：專注目標",
  ["Show: Party 1"] = "顯示：隊伍 1",
