  ["Show: Party 3"] = "顯示：隊伍 3",
  ["Show: Party 4"] = "顯示：隊伍 4",
  ["Show: Target"] = "顯示：目標",
  ["Show: You"] = "顯示：你",
  ["Shows <Guild> under friendly players' names in name-only mode."] = "在僅名字模式下在友方玩家名字下顯示 <公會>。",
  ["Shows Gladiator progress on the card."] = "在卡片上顯示角鬥士進度。",
