  ["Shows Phoenix action bar 1 and hides the matching Blizzard bar."] = "顯示 Phoenix 快捷列 1 並隱藏對應的暴雪快捷列。",
  ["Shows Phoenix action bar 10."] = "顯示 Phoenix 快捷列 10。",
