  ["Shows Phoenix action bar 3 and hides the matching Blizzard bar."] = "顯示 Phoenix 快捷列 3 並隱藏對應的暴雪快捷列。",
  ["Shows Phoenix action bar 4 and hides the matching Blizzard bar."] = "顯示 Phoenix 快捷列 4 並隱藏對應的暴雪快捷列。",
  ["Shows Phoenix action bar 5 and hides the matching Blizzard bar."] = "顯示 Phoenix 快捷列 5 並隱藏對應的暴雪快捷列。",
  ["Shows Phoenix action bar 6 and hides the matching Blizzard bar."] = "顯示 Phoenix 快捷列 6 並隱藏對應的暴雪快捷列。",
