  ["Shows Strategist progress on the card."] = "在卡片上顯示戰略家進度。",
  ["Shows a cast bar for this frame."] = "為此框架顯示施法條。",
  ["Shows a red swipe on buttons you cannot use because you are stunned, silenced or locked out."] = "在你因昏迷、沉默或法術封鎖而無法使用的按鈕上顯示紅色遮罩。",
  ["Shows a small F at the corner of your focus target's plate."] = "在你專注目標的名條角落顯示小 F。",
  ["Shows an NPC's title, such as <Innkeeper> or <Flight Master>, under its name."] = "在 NPC 名字下顯示其頭銜，例如 <旅店老闆> 或 <飛行管理員>。",
  ["Shows auras you gain in Spark."] = "在 Spark 中顯示你獲得的光環。",
  ["Shows auras you lose in Spark."] = "在 Spark 中顯示你失去的光環。",
  ["Shows buffs icons on each frame."] = "在每個框架上顯示增益圖示。",
  ["Shows buffs on the boss frame."] = "在首領框架上顯示增益。",
  ["Shows buffs on the focus frame."] = "在專注目標框架上顯示增益。",
  ["Shows buffs on the focus target frame."] = "在專注目標框架上顯示增益。",
  ["Shows buffs on the pet frame."] = "在寵物框架上顯示增益。",
  ["Shows buffs on the player frame."] = "在玩家框架上顯示增益。",
  ["Shows buffs on the target frame."] = "在目標框架上顯示增益。",
  ["Shows buffs on the target of target frame."] = "在目標的目標框架上顯示增益。",
  ["Shows casts and channels under enemy plates, with the shield for casts you cannot interrupt."] = "在敵方名條下顯示施法和引導，無法打斷的施法帶盾牌。",
  ["Shows currency in Spark."] = "在 Spark 中顯示貨幣。",
  ["Shows damage absorbs after the health fill and heal absorbs on it."] = "在生命填充後顯示傷害吸收，在其上顯示治療吸收。",
  ["Shows damage you take in Spark."] = "在 Spark 中顯示你受到的傷害。",
  ["Shows damage your pet takes in Spark."] = "在 Spark 中顯示寵物受到的傷害。",
  ["Shows debuffs icons on each frame."] = "在每個框架上顯示減益圖示。",
  ["Shows debuffs on the boss frame."] = "在首領框架上顯示減益。",
  ["Shows debuffs on the focus frame."] = "在專注目標框架上顯示減益。",
  ["Shows debuffs on the focus target frame."] = "在專注目標框架上顯示減益。",
  ["Shows debuffs on the pet frame."] = "在寵物框架上顯示減益。",
  ["Shows debuffs on the player frame."] = "在玩家框架上顯示減益。",
  ["Shows debuffs on the target frame."] = "在目標框架上顯示減益。",
  ["Shows debuffs on the target of target frame."] = "在目標的目標框架上顯示減益。",
  ["Shows each friend's note under their name."] = "在每位好友名字下顯示其備註。",
  ["Shows entering combat in Spark."] = "在 Spark 中顯示進入戰鬥。",
  ["Shows experience in Spark."] = "在 Spark 中顯示經驗。",
  ["Shows heals you get in Spark."] = "在 Spark 中顯示你受到的治療。",
  ["Shows heals your pet gets in Spark."] = "在 Spark 中顯示寵物受到的治療。",
  ["Shows hits you avoid (dodge, parry, absorb...) in Spark."] = "在 Spark 中顯示你避免的攻擊（躲閃、招架、吸收……）。",
  ["Shows honor in Spark."] = "在 Spark 中顯示榮譽。",
  ["Shows how many bosses a raid group has already killed and adds the filter word bossesdown. Uses a game function Blizzard's own list uses; it turns off by itself if a patch removes it."] = "顯示團隊已擊殺的首領數量，並新增過濾詞 bossesdown。使用暴雪自己列表所用的遊戲函式；如果補丁移除它會自動關閉。",
  ["Shows how many minutes ago the group was listed."] = "顯示隊伍釋出於多少分鐘前。",
  ["Shows interrupt counts for your group (from the Embers meter data)."] = "顯示你隊伍的打斷次數（來自 Embers 統計資料）。",
  ["Shows item or potion ready in Spark."] = "在 Spark 中顯示物品或藥水就緒。",
  ["Shows leaving combat in Spark."] = "在 Spark 中顯示離開戰鬥。",
  ["Shows loot in Spark."] = "在 Spark 中顯示拾取。",
  ["Shows macro names on action buttons."] = "在動作按鈕上顯示巨集名稱。",
  ["Shows money in Spark."] = "在 Spark 中顯示金錢。",
  ["Shows only the button, without the decorative frame around it."] = "只顯示按鈕，不顯示周圍的裝飾框。",
  ["Shows only the zone ability button, without its frame."] = "只顯示區域技能按鈕，不顯示其框架。",
  ["Shows predicted incoming heals after the health fill."] = "在生命填充後顯示預計即將到來的治療。",
  ["Shows raid buffs someone in your group can give that you are missing."] = "顯示隊伍中有人能提供而你缺少的團隊增益。",
  ["Shows raid target markers above plates."] = "在名條上方顯示團隊目標標記。",
  ["Shows reputation in Spark."] = "在 Spark 中顯示聲望。",
  ["Shows shared battle-res charges and whether you can get Bloodlust again."] = "顯示共享的戰複次數以及你是否能再次獲得嗜血。",
  ["Shows skill ups in Spark."] = "在 Spark 中顯示技能提升。",
  ["Shows the DR tray only on enemy healers."] = "僅在敵方治療上顯示遞減托盤。",
  ["Shows the Phoenix UI button on the minimap edge. Left-click opens options, right-click opens Studio, Shift-click opens Sentinel, drag to move."] = "在小地圖邊緣顯示 Phoenix UI 按鈕。左鍵開啟選項，右鍵開啟 Studio，Shift 點選開啟 Sentinel，拖動可移動。",
  ["Shows the PvP flag icon on unit frames."] = "在單位框架上顯示 PvP 標記圖示。",
  ["Shows the ability icon beside each bar."] = "在每個條旁顯示技能圖示。",
  ["Shows the achievement ID on tooltips."] = "在滑鼠提示中顯示成就 ID。",
  ["Shows the area poi ID on tooltips."] = "在滑鼠提示中顯示區域興趣點 ID。",
  ["Shows the artifact power ID on tooltips."] = "在滑鼠提示中顯示神器能量 ID。",
  ["Shows the battle pet species ID on tooltips."] = "在滑鼠提示中顯示戰鬥寵物種類 ID。",
  ["Shows the bonus ID on tooltips. Off by default because it is long or rarely needed."] = "在滑鼠提示中顯示加成 ID。預設關閉，因為它很長且很少需要。",
  ["Shows the bound key on each action button."] = "在每個動作按鈕上顯示繫結按鍵。",
  ["Shows the buffs from your own list below when they are missing."] = "你下方列表中的增益缺失時顯示。",
  ["Shows the cast bar in the resource stack."] = "在資源堆疊中顯示施法條。",
  ["Shows the cast bar only on enemy healers."] = "僅在敵方治療上顯示施法條。",
  ["Shows the class resource in the resource stack."] = "在資源堆疊中顯示職業資源。",
  ["Shows the crafted quality badge on items in the custom cooldown bar."] = "在自訂冷卻條中的物品上顯示製造品質徽章。",
  ["Shows the criteria ID on tooltips."] = "在滑鼠提示中顯示條件 ID。",
  ["Shows the currencies you track on the backpack."] = "在揹包上顯示你追蹤的貨幣。",
  ["Shows the currency ID on tooltips."] = "在滑鼠提示中顯示貨幣 ID。",
  ["Shows the damage column on the run summary card."] = "在鑰石結算卡片上顯示傷害列。",
  ["Shows the deaths column on the run summary card."] = "在鑰石結算卡片上顯示死亡列。",
  ["Shows the dungeon score a timed run of this key would give against your best (an estimate)."] = "顯示限時完成此鑰石相對你最佳成績可獲得的地城評分（估算）。",
  ["Shows the elite / rare icon on unit frames."] = "在單位框架上顯示精英/稀有圖示。",
  ["Shows the enchant ID on tooltips."] = "在滑鼠提示中顯示附魔 ID。",
  ["Shows the equipment set ID on tooltips."] = "在滑鼠提示中顯示裝備方案 ID。",
  ["Shows the expansion ID on tooltips."] = "在滑鼠提示中顯示資料片 ID。",
  ["Shows the follower ability ID on tooltips."] = "在滑鼠提示中顯示追隨者技能 ID。",
  ["Shows the game's suggested next spell (Assisted Combat) as one icon. Move it in Studio."] = "以一個圖示顯示遊戲建議的下一個法術（輔助戰鬥）。在 Studio 中移動它。",
  ["Shows the gem ID on tooltips."] = "在滑鼠提示中顯示寶石 ID。",
  ["Shows the global cooldown bar in the resource stack."] = "在資源堆疊中顯示公共冷卻條。",
  ["Shows the group leader icon on unit frames."] = "在單位框架上顯示隊長圖示。",
  ["Shows the healing column on the run summary card."] = "在鑰石結算卡片上顯示治療列。",
  ["Shows the health bar in the resource stack."] = "在資源堆疊中顯示生命條。",
  ["Shows the icon ID on tooltips."] = "在滑鼠提示中顯示圖示 ID。",
  ["Shows the in combat icon on unit frames."] = "在單位框架上顯示戰鬥中圖示。",
  ["Shows the incoming scroll area."] = "顯示受到區域。",
  ["Shows the item ID on tooltips."] = "在滑鼠提示中顯示物品 ID。",
  ["Shows the items from the shared item list (potions, healthstones, on-use trinkets) with their cooldowns. Display only: the clickable item bar is part of Action Bars."] = "顯示共享物品列表中的物品（藥水、治療石、主動飾品）及其冷卻。僅顯示：可點選的物品條屬於快捷列。",
  ["Shows the kicks column on the run summary card."] = "在鑰石結算卡片上顯示打斷列。",
  ["Shows the leader's Mythic+ score in the colour source you picked (Blizzard, Raider.IO or your own gradient)."] = "以你選擇的顏色來源（暴雪、Raider.IO 或你自己的漸變）顯示隊長的傳奇鑰石評分。",
  ["Shows the leader's realm language ([DE], [FR] ...) when an addon with LibRealmInfo is loaded."] = "載入帶 LibRealmInfo 的插件時顯示隊長的伺服器語言（[DE]、[FR]……）。",
  ["Shows the macro ID on tooltips."] = "在滑鼠提示中顯示巨集 ID。",
  ["Shows the mount ID on tooltips."] = "在滑鼠提示中顯示坐騎 ID。",
  ["Shows the notifications scroll area."] = "顯示通知區域。",
  ["Shows the npc ID on tooltips."] = "在滑鼠提示中顯示 NPC ID。",
  ["Shows the object ID on tooltips."] = "在滑鼠提示中顯示物體 ID。",
  ["Shows the outgoing scroll area."] = "顯示輸出區域。",
  ["Shows the pet ability ID on tooltips."] = "在滑鼠提示中顯示寵物技能 ID。",
  ["Shows the power bar in the resource stack."] = "在資源堆疊中顯示能量條。",
  ["Shows the quest ID on tooltips."] = "在滑鼠提示中顯示任務 ID。",
  ["Shows the raid markers icon on unit frames."] = "在單位框架上顯示團隊標記圖示。",
  ["Shows the remaining time on the cast bar."] = "在施法條上顯示剩餘時間。",
  ["Shows the resting (player) icon on unit frames."] = "在單位框架上顯示休息（玩家）圖示。",
  ["Shows the seconds left on private auras."] = "在私有光環上顯示剩餘秒數。",
  ["Shows the seconds left on the bar."] = "在條上顯示剩餘秒數。",
  ["Shows the shared combat and encounter timer in the title."] = "在標題中顯示共享的戰鬥和首領戰計時。",
  ["Shows the spell ID on tooltips."] = "在滑鼠提示中顯示法術 ID。",
  ["Shows the spell icon beside the cast bar."] = "在施法條旁顯示法術圖示。",
  ["Shows the spell icon left of the cast bar."] = "在施法條左側顯示法術圖示。",
  ["Shows the spell name on the cast bar."] = "在施法條上顯示法術名稱。",
  ["Shows the spell or item icon beside a line."] = "在行旁顯示法術或物品圖示。",
  ["Shows the spell or item tooltip when the pointer is over an action button."] = "滑鼠指向動作按鈕時顯示法術或物品提示。",
  ["Shows the spell tooltip when you point at an icon."] = "指向圖示時顯示法術提示。",
  ["Shows the static (sticky) scroll area."] = "顯示靜態（固定）區域。",
  ["Shows the talent ID on tooltips."] = "在滑鼠提示中顯示天賦 ID。",
  ["Shows the time left as numbers on each cooldown icon (the game's own countdown)."] = "在每個冷卻圖示上以數字顯示剩餘時間（遊戲自帶倒計時）。",
  ["Shows the time left on a cooldown as numbers on the button (drawn by the game's own countdown)."] = "在按鈕上以數字顯示冷卻剩餘時間（由遊戲自帶倒計時繪製）。",
  ["Shows the time left on the cast bar."] = "在施法條上顯示剩餘時間。",
  ["Shows the time left on the invite under the Enter button. The time comes from the shared queue timer (also used by the minimap eye); set the dungeon invite length with 'Dungeon queue-pop time'."] = "在進入按鈕下顯示邀請剩餘時間。時間來自共享的排隊計時器（小地圖眼睛也使用）；用“地城排隊彈出時間”設定地城邀請時長。",
  ["Shows the time on the minimap."] = "在小地圖上顯示時間。",
  ["Shows the title bar with meter, fight and timer."] = "顯示帶統計型別、戰鬥和計時器的標題欄。",
  ["Shows the totem bars in the resource stack."] = "在資源堆疊中顯示圖騰條。",
  ["Shows the trait definition ID on tooltips. Off by default because it is long or rarely needed."] = "在滑鼠提示中顯示特質定義 ID。預設關閉，因為它很長且很少需要。",
  ["Shows the trait entry ID on tooltips. Off by default because it is long or rarely needed."] = "在滑鼠提示中顯示特質條目 ID。預設關閉，因為它很長且很少需要。",
  ["Shows the trait node ID on tooltips. Off by default because it is long or rarely needed."] = "在滑鼠提示中顯示特質節點 ID。預設關閉，因為它很長且很少需要。",
  ["Shows the transmog source ID on tooltips."] = "在滑鼠提示中顯示幻化來源 ID。",
  ["Shows the transmog visual ID on tooltips."] = "在滑鼠提示中顯示幻化外觀 ID。",
  ["Shows the trinket only on enemy healers (needs their spec, known from the preparation phase)."] = "僅在敵方治療上顯示飾品（需要其專精，在準備階段可知）。",
  ["Shows the unit's name on enemy plates."] = "在敵方名條上顯示單位名字。",
  ["Shows the vignette ID on tooltips."] = "在滑鼠提示中顯示稀有標記 ID。",
  ["Shows the zone name on the minimap."] = "在小地圖上顯示區域名稱。",
