  ["Shows whether your enemy forces are ahead of or behind an even pace for +1, +2 and +3."] = "顯示你的敵方部隊進度相對 +1、+2 和 +3 的均速是領先還是落後。",
  ["Shows which roles the group still needs."] = "顯示隊伍仍需要哪些職責。",
  ["Shows who pinged the minimap for a few seconds."] = "顯示幾秒鐘內誰在小地圖上發了訊號。",
  ["Shows your /way waypoint at the top; click it to clear."] = "在頂部顯示你的 /way 路徑點；點選清除。",
  ["Shows your combo points, holy power, chi and similar under your target's plate. Needs the Resource Bars add-on loaded (it does not have to be switched on)."] = "在目標名條下顯示你的連擊點、神聖能量、真氣等。需要載入資源條插件（不必開啟）。",
  ["Shows your damage in Spark."] = "在 Spark 中顯示你的傷害。",
  ["Shows your frame even when you are not in a group."] = "即使不在隊伍中也顯示你的框架。",
  ["Shows your heals in Spark."] = "在 Spark 中顯示你的治療。",
  ["Shows your interrupt and its cooldown beside the cast bar."] = "在施法條旁顯示你的打斷及其冷卻。",
  ["Shows your interrupt and its cooldown next to each cast, so you see at a glance whether your kick is ready."] = "在每個施法旁顯示你的打斷及其冷卻，一眼就能看出打斷是否就緒。",
  ["Shows your misses in Spark."] = "在 Spark 中顯示你的未命中。",
  ["Shows your notes for your target or the last boss, only out of combat. Move it in Studio."] = "僅在非戰鬥時顯示你為目標或上一個首領寫的筆記。在 Studio 中移動它。",
  ["Shows your own class buffs that are missing, like rogue poisons or a paladin aura."] = "顯示你缺失的本職業增益，如潛行者毒藥或聖騎士光環。",
  ["Shows your quest progress for an enemy, such as \"Void Acolytes slain: 3/8\", under its name."] = "在敵人名字下顯示你對其的任務進度，例如“虛空侍僧已殺死：3/8”。",
