  ["The action page bar 1 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 1 的動作頁。",
  ["The action page bar 10 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 10 的動作頁。",
  ["The action page bar 2 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 2 的動作頁。",
  ["The action page bar 3 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 3 的動作頁。",
  ["The action page bar 4 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 4 的動作頁。",
  ["The action page bar 5 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 5 的動作頁。",
  ["The action page bar 6 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 6 的動作頁。",
  ["The action page bar 7 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 7 的動作頁。",
  ["The action page bar 8 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 8 的動作頁。",
  ["The action page bar 9 shows while its paging modifier is held."] = "按住翻頁修飾鍵時顯示快捷列 9 的動作頁。",
  ["The bar stays invisible until you point at it."] = "快捷列保持不可見，直到你指向它。",
  ["The bar turns red when this many seconds are left."] = "剩餘這麼多秒時計量條變紅。",
  ["The border and backdrop style of every plate. Each part below can still be changed on its own."] = "每個名條的邊框和背景樣式。下面每個部分仍可單獨更改。",
  ["The border around every Phoenix window, frame and icon outline."] = "每個 Phoenix 視窗、框架和圖示輪廓的邊框。",
  ["The clock block uses 24-hour time."] = "時鐘模組使用 24 小時制。",
  ["The countdown bar turns red with this many seconds left."] = "剩餘這麼多秒時倒計時條變紅。",
  ["The docked bar fades to this while the mouse is away; 1 never fades."] = "滑鼠離開時停靠條淡出到此值；1 表示從不淡出。",
  ["The dungeon ready pop-up ignores clicks for a moment so a stray click cannot accept or leave."] = "地城就緒彈窗短時間內忽略點選，防止誤點接受或離開。",
  ["The enemy's racial ability. Racials that share a cooldown with the trinket lock when the trinket is used."] = "敵人的種族技能。與飾品共享冷卻的種族技能在使用飾品時鎖定。",
  ["The enemy's spec icon, shown from the preparation room on."] = "敵人的專精圖示，從準備室開始顯示。",
  ["The enemy's trinket with its cooldown, from the game's own data."] = "敵人的飾品及其冷卻，來自遊戲自身資料。",
  ["The first time Phoenix bars turn on, each bar starts where your Edit Mode layout had it. Bars you already moved are kept. /pui abcapture copies them again."] = "Phoenix 快捷列首次開啟時，每個條從你編輯模式佈局中的位置開始。已經移動過的條保持不變。/pui abcapture 會再次複製它們。",
  ["The frame around every button. Each part (border, zoom, fonts) can still be changed on its own."] = "每個按鈕周圍的框。每個部分（邊框、縮放、字型）仍可單獨更改。",
  ["The game's nameplate scale; 0 keeps the game's value."] = "遊戲的名條縮放；0 保留遊戲的值。",
  ["The game's own target plate scale; 0 keeps the game's value. Phoenix's target size above works on top of it."] = "遊戲自身的目標名條縮放；0 保留遊戲的值。上方 Phoenix 的目標大小在此基礎上生效。",
  ["The header, background and border fade out and come back while your mouse is over the window; the rows stay."] = "標題、背景和邊框會淡出，滑鼠在視窗上時恢復；行保持顯示。",
  ["The header, dropdowns and backdrop of Blizzard's meter windows fade out and come back while the mouse is over them."] = "暴雪統計視窗的標題、下拉框和背景會淡出，滑鼠在其上時恢復。",
  ["The health bar under unit tooltips."] = "單位滑鼠提示下的生命條。",
  ["The item bar stays faded until you point at it."] = "物品條保持淡出，直到你指向它。",
  ["The latest cast glows."] = "最近的施法發光。",
  ["The line cap for this area in big pulls."] = "大規模拉怪時此區域的行數上限。",
  ["The look of the button on the minimap that opens the bin."] = "小地圖上開啟收納框的按鈕外觀。",
  ["The meter type and fight dropdowns in the header get the Phoenix look."] = "標題中的統計型別和戰鬥下拉框使用 Phoenix 外觀。",
  ["The mouse wheel scrolls through everyone in the fight; there is no scroll bar."] = "滑鼠滾輪滾動檢視戰鬥中的每個人；沒有捲軸。",
  ["The pet bar stays faded until you point at it."] = "寵物條保持淡出，直到你指向它。",
  ["The popup closes after the delay below once the mouse leaves it."] = "滑鼠離開後，彈窗在下面的延遲後關閉。",
  ["The popup closes and the bar hides when combat starts; the bar comes back after combat."] = "戰鬥開始時彈窗關閉、條隱藏；脫戰後條恢復。",
  ["The profile this specialization uses. No change keeps whatever profile is active."] = "此專精使用的配置檔案。“不更改”保持當前啟用的配置檔案。",
  ["The raid layout used for every raid size when automatic picking is off."] = "關閉自動選擇時所有團隊規模使用的團隊佈局。",
  ["The same error alerts at most once in this many seconds (it is always counted)."] = "同一錯誤在這麼多秒內最多提醒一次（總會被計數）。",
  ["The scoreboard stays open after you leave the battleground."] = "離開戰場後記分板保持開啟。",
  ["The shared Phoenix cast bar under each enemy, with your kick state."] = "每個敵人下方共享的 Phoenix 施法條，帶你的打斷狀態。",
  ["The single highlight colour of Phoenix UI. Class uses your class colour."] = "Phoenix UI 的唯一強調色。“職業”使用你的職業顏色。",
  ["The spec icon shows the enemy's most important aura while it lasts (crowd control, big defensive or important, in your order)."] = "專精圖示在敵人最重要的光環持續期間顯示它（控制、大減傷或重要，按你的順序）。",
  ["The spell whose range is checked. 0 uses your interrupt."] = "檢查距離所用的法術。0 使用你的打斷。",
  ["The stance bar stays faded until you point at it."] = "姿態條保持淡出，直到你指向它。",
  ["The strip stops moving while you point at it."] = "指向時捲軸停止移動。",
  ["The vehicle exit button stays faded until you point at it."] = "離開載具按鈕保持淡出，直到你指向它。",
  ["Theme"] = "主題",
  ["Theme accent or your class colour."] = "主題強調色或你的職業顏色。",
  ["There is no combat log in Midnight: Spark works out your hits from your own casts."] = "至暗之夜中沒有戰鬥日誌：Spark 根據你自己的施法推算你的命中。",
  ["Thick or thin ring."] = "粗環或細環。",
  ["Thickness of pixel-line borders (0 hides them)."] = "畫素線邊框的粗細（0 隱藏）。",
  ["Thin Phoenix scroll bars in every skinned window."] = "每個美化視窗中的細 Phoenix 捲軸。",
  ["Thin accent border around each window."] = "每個視窗周圍的細強調色邊框。",
  ["Thin accent border around the panel."] = "面板周圍的細強調色邊框。",
  ["Thin lines between blocks."] = "模組之間的細線。",
  ["Thin rail with an accent thumb."] = "帶強調色滑塊的細滑軌。",
  ["Thin scroll marker"] = "細滾動標記",
  ["This week's wins and losses, conquest earned and the PvP row of the Great Vault on one line."] = "本週勝負、獲得的征服點數和巨集偉寶庫的 PvP 行顯示在一行。",
  ["Threat colour style"] = "仇恨顏色樣式",
  ["Threat colours"] = "仇恨顏色",
  ["Threat glow"] = "仇恨光效",
  ["Threat warning at (%)"] = "仇恨警告閾值（%）",
