  ["Threat: as wanted"] = "仇恨：符合預期",
  ["Threat: changing"] = "仇恨：變化中",
  ["Threat: wrong"] = "仇恨：錯誤",
  ["Threshold sounds"] = "閾值音效",
  ["Tick a box to show health bars for that kind of friendly unit in that content. Unticked shows the name only (the default everywhere). Inside instances the game may keep friendly plates for itself; then its own plate shows."] = "勾選後在該內容中為該類友方單位顯示生命條。未勾選只顯示名字（各處預設）。副本中游戲可能自己保留友方名條；此時顯示遊戲的名條。",
  ["Tick a topic for the content types where it may be announced. Everything starts unticked."] = "為可通告的內容型別勾選主題。預設全部未勾選。",
  ["Tick an option for the content types where it should apply. Everything starts unticked; sound options return to your own values when they stop applying."] = "為應生效的內容型別勾選選項。預設全部未勾選；音效選項停止生效時恢復你自己的值。",
  ["Tick marks for your channels: spell ID = number of ticks, comma-separated, e.g. 15407=6, 5143=5."] = "引導法術的刻度：法術 ID = 跳數，用逗號分隔，例如 15407=6, 5143=5。",
  ["Tick marks on the timer bar where +3 and +2 run out."] = "計時條上 +3 和 +2 時間耗盡處的刻度。",
  ["Ticket status"] = "工單狀態",
  ["Time format"] = "時間格式",
  ["Time in front of each line. Lines the game keeps secret in restricted content are shown unchanged."] = "每行前的時間。受限內容中游戲保密的行原樣顯示。",
  ["Time left on the cast bar."] = "施法條上的剩餘時間。",
  ["Timer colour inside the refresh window."] = "重新整理視窗內的計時器顏色。",
  ["Timer format"] = "計時器格式",
  ["Timer shows in"] = "計時器顯示於",
  ["Timer text size"] = "計時器文字大小",
  ["Times Phoenix's registered entry points and Ticker jobs (/pui profile). Off costs nothing: no wrappers exist while it is off."] = "統計 Phoenix 已註冊入口和 Ticker 任務的耗時（/pui profile）。關閉時無任何開銷：關閉時不存在包裝函式。",
  ["Timestamp colour (hex)"] = "時間戳顏色（十六進位制）",
  ["Timestamps"] = "時間戳",
  ["Timestamps become links that open the line in the copy box."] = "時間戳變為連結，可在複製框中開啟該行。",
  ["Tint of buttons you cannot use right now."] = "當前無法使用的按鈕的色調。",
  ["Tint of buttons you lack the mana, energy or other power for."] = "缺少法力、能量或其他資源的按鈕的色調。",
