  ["Trinket and racial size"] = "飾品和種族技能大小",
  ["Trinket for healers only"] = "僅治療顯示飾品",
  ["Turn off Blizzard's combat notifications"] = "關閉暴雪的戰鬥通知",
  ["Turn off Blizzard's incoming combat text"] = "關閉暴雪的受到戰鬥文字",
  ["Turn off Blizzard's outgoing combat text"] = "關閉暴雪的輸出戰鬥文字",
  ["Turn on the client's taint log until logout so blocked actions can be traced."] = "開啟客戶端汙染日誌直到登出，以便追蹤被阻止的操作。",
  ["Turns /combatlog on in the content types ticked below and off elsewhere (only a log Flow started). Raids and Mythic+ are ticked to start with."] = "在下面勾選的內容型別中開啟 /combatlog，其他地方關閉（僅限 Flow 開啟的日誌）。團隊副本和傳奇鑰石預設勾選。",
  ["Turns :name: codes such as :star: or :tank: into icons, with suggestions while you type."] = "將 :star: 或 :tank: 等 :name: 程式碼轉換為圖示，輸入時提供建議。",
  ["Turns off the game's tutorial pop-ups; your setting comes back when this is off."] = "關閉遊戲的教程彈窗；關閉此項後恢復你的設定。",
  ["Turns on the game's own enemy DR tracking (setting spellDiminishPVPEnemiesEnabled) and shows it in Phoenix's tray. Off: no DR is shown. Your old value comes back when this goes off."] = "開啟遊戲自帶的敵方遞減追蹤（設定 spellDiminishPVPEnemiesEnabled）並在 Phoenix 托盤中顯示。關閉：不顯示遞減。關閉時恢復你原來的值。",
  ["Turns the Phoenix filter for this category on or off without losing your chips."] = "開啟或關閉此分類的 Phoenix 過濾，不會丟失你的標籤。",
  ["Turns the game's friendly nameplates on or off for you. Your own value comes back when Phoenix nameplates turn off."] = "為你開啟或關閉遊戲的友方名條。關閉 Phoenix 名條後恢復你自己的值。",
  ["Type /keys to list your key, your alts' keys and your group's keys (/pui keys always works)."] = "輸入 /keys 列出你的鑰石、小號的鑰石和隊伍的鑰石（/pui keys 始終可用）。",
  ["Types the confirmation word when deleting a good item."] = "刪除好物品時自動輸入確認詞。",
  ["Typing : and a few letters shows matching emoji; click one or press Tab to insert it."] = "輸入 : 和幾個字母會顯示匹配的表情；點選或按 Tab 插入。",
  ["Typing in the add-friend box lists matching guild members and recent players; click one to fill the box."] = "在新增好友框中輸入會列出匹配的公會成員和最近玩家；點選即可填入。",
  ["UI errors"] = "介面錯誤",
  ["Uninterruptible colour"] = "不可打斷顏色",
  ["Uninterruptible colour of plate cast bars."] = "名條施法條的不可打斷顏色。",
  ["Unit frames"] = "單位框架",
  ["Unlocked glow"] = "解鎖光效",
  ["Unread badges"] = "未讀徽章",
  ["Unusable colour"] = "不可用顏色",
  ["Upgradable gear shows how many ranks are left and about how many crests they cost."] = "可升級裝備顯示剩餘等級數以及大約需要多少紋章。",
  ["Upgrade hint"] = "升級提示",
  ["Upgrade star"] = "升級星標",
  ["Upgrade track"] = "升級軌道",
  ["Use my class colours"] = "使用我的職業顏色",
  ["Use one font in every Phoenix module, or keep each module's own font choice."] = "在所有 Phoenix 模組中使用同一字型，或保留每個模組各自的字型選擇。",
  ["Use the profile you picked for raid, Mythic+, arena and other content automatically. Applies when you enter, never in combat."] = "自動使用你為團隊副本、傳奇鑰石、競技場和其他內容選擇的配置檔案。進入時應用，戰鬥中從不應用。",
  ["Used when Colour by debuff type is off."] = "關閉“按減益型別著色”時使用。",
  ["Used when Group health colour is Custom."] = "隊伍生命顏色為“自訂”時使用。",
  ["Used when Health colour is Custom."] = "生命顏色為“自訂”時使用。",
  ["Uses the Party, Raid up to 10, Raid up to 20 or Raid up to 40 layout automatically as people join and leave. Turn off to always use one raid layout."] = "隨著玩家加入和離開，自動使用隊伍、團隊（最多 10）、團隊（最多 20）或團隊（最多 40）佈局。關閉則始終使用一種團隊佈局。",
  ["Utility cooldowns"] = "輔助冷卻",
  ["Utility cooldowns: Phoenix layout"] = "輔助冷卻：Phoenix 佈局",
  ["Utility cooldowns: growth"] = "輔助冷卻：增長方向",
  ["Utility cooldowns: icon size"] = "輔助冷卻：圖示大小",
  ["Utility cooldowns: per row"] = "輔助冷卻：每行數量",
  ["Utility cooldowns: spacing"] = "輔助冷卻：間距",
  ["Vault"] = "Vault",
  ["Vehicle exit"] = "離開載具",
  ["Vehicle exit button"] = "離開載具按鈕",
  ["Vehicle exit button button size"] = "離開載具按鈕大小",
  ["Vehicle exit button fade opacity"] = "離開載具按鈕淡出不透明度",
  ["Vehicle exit button fade until mouse-over"] = "離開載具按鈕淡出直到滑鼠懸停",
  ["Vehicle seats"] = "載具座位",
  ["Vertical distance from the cursor for the left/right cursor positions."] = "游標左/右位置時與游標的縱向距離。",
  ["Vertical spacing when stacked"] = "堆疊時的垂直間距",
  ["View"] = "檢視",
  ["Viewer layout"] = "檢視器佈局",
  ["Viewer opens on"] = "檢視器開啟於",
  ["Viewer shows"] = "檢視器顯示",
  ["Voice deafen button"] = "語音靜聽按鈕",
  ["Voice mute button"] = "語音靜音按鈕",
  ["Warlock colour"] = "術士顏色",
  ["Warn at (seconds left)"] = "警告時間（剩餘秒數）",
  ["Warn once on many new errors"] = "大量新錯誤時只警告一次",
  ["Warning level for the low durability warning."] = "低耐久度警告的閾值。",
  ["Warns once when any item drops to the threshold."] = "任一物品耐久降到閾值時警告一次。",
  ["Warrior colour"] = "戰士顏色",
  ["Waypoint line"] = "路徑點連線",
  ["Waypoints (/way): when another addon does this"] = "路徑點（/way）：當其他插件做此事時",
  ["WeakAuras options"] = "WeakAuras 選項",
  ["Weapon enchants"] = "武器附魔",
  ["Weapon oil in instances"] = "副本中的武器油",
  ["Web addresses in chat become links; click one to copy it."] = "聊天中的網址變為連結；點選可複製。",
  ["Weekly record, conquest and Great Vault"] = "每週戰績、征服點數和巨集偉寶庫",
  ["What /gg says."] = "/gg 說什麼。",
  ["What a left click on a quest does. Right-click opens details, Ctrl-click copies a Wowhead link, Alt-click stops tracking."] = "左鍵點選任務時的操作。右鍵開啟詳情，Ctrl 點選複製 Wowhead 連結，Alt 點選停止追蹤。",
  ["What a middle click on the minimap opens. The micro menu lists Character, Spellbook, Talents, Collections, Group Finder and more."] = "中鍵點選小地圖開啟的內容。微型選單包括角色、法術書、天賦、收藏、隊伍查詢器等。",
  ["What dragged elements snap to while Snap is on: the grid, other elements' edges and centres, or both."] = "開啟吸附時拖動元素吸附到：網格、其他元素的邊緣和中心，或兩者。",
  ["What each party member is targeting, as small frames beside the party."] = "以小框架在隊伍旁顯示每位隊員的目標。",
  ["What the DR tray attaches to. Move it further with the offsets."] = "遞減托盤附著的物件。用偏移進一步移動。",
  ["What the center text zone shows."] = "中間文字區域顯示的內容。",
  ["What the left text zone shows."] = "左側文字區域顯示的內容。",
  ["What the power text zone shows."] = "能量文字區域顯示的內容。",
  ["What the right text zone shows."] = "右側文字區域顯示的內容。",
  ["What to announce, by content"] = "按內容決定通告什麼",
  ["What window 1 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "視窗 1 顯示的內容。仇恨列出你隊伍對你目標的仇恨。也可左鍵點選視窗標題切換。",
  ["What window 2 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "視窗 2 顯示的內容。仇恨列出你隊伍對你目標的仇恨。也可左鍵點選視窗標題切換。",
  ["What window 3 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "視窗 3 顯示的內容。仇恨列出你隊伍對你目標的仇恨。也可左鍵點選視窗標題切換。",
  ["What window 4 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "視窗 4 顯示的內容。仇恨列出你隊伍對你目標的仇恨。也可左鍵點選視窗標題切換。",
  ["What you see when a key finishes: a summary card with time, score change and everyone's numbers, a chat line, or nothing."] = "鑰石完成時你看到的：帶時間、分數變化和每個人資料的彙總卡片、一行聊天，或什麼都沒有。",
  ["When !KalielsTracker, KalielsTracker is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 !KalielsTracker, KalielsTracker 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When AutoQueue is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 AutoQueue 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When Baganator, Bagnon, AdiBags, ArkInventory, BetterBags, Combuctor, LiteBag is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 Baganator, Bagnon, AdiBags, ArkInventory, BetterBags, Combuctor, LiteBag 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When Bartender4, Dominos, ElvUI, EllesmereUIActionBars, ConsolePort_Bar, LUI is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 Bartender4, Dominos, ElvUI, EllesmereUIActionBars, ConsolePort_Bar, LUI 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When BigWigs is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 BigWigs 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When BigWigs, DBM-Core is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 BigWigs, DBM-Core 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When BugSack is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 BugSack 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When Details, Skada, Recount is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 Details, Skada, Recount 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When EllesmereUICooldownManager, BetterCooldownManager, CooldownManagerCentered is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 EllesmereUICooldownManager, BetterCooldownManager, CooldownManagerCentered 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When EllesmereUIResourceBars, SenseiClassResourceBar, PersonalResourceReskin is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 EllesmereUIResourceBars, SenseiClassResourceBar, PersonalResourceReskin 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When MikScrollingBattleText, Parrot, xCT+ is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 MikScrollingBattleText, Parrot, xCT+ 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When MythicDungeonTools is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 MythicDungeonTools 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When Prat-3.0, Chattynator, Chatter, Glass, WIM, BasicChatMods is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 Prat-3.0, Chattynator, Chatter, Glass, WIM, BasicChatMods 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When PremadeGroupsFilter is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 PremadeGroupsFilter 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When Questie is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 Questie 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When Studio shows each mover's name."] = "Studio 何時顯示每個移動器的名稱。",
  ["When TomTom is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "載入 TomTom 時，選擇 Phoenix 是否也執行此功能。兩個插件都不會被禁用。",
  ["When Unit Frames attaches these bars under your player frame, they take its width. Off keeps the width set here."] = "單位框架將這些條附加在玩家框架下方時，它們採用其寬度。關閉則保持此處設定的寬度。",
  ["When WarpDeplete, MythicPlusTimer, AngryKeystones is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 WarpDeplete, MythicPlusTimer, AngryKeystones 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When a battleground ends, a countdown leaves for you. Cancel it or leave at once. Arenas are never left for you."] = "戰場結束時，會開始自動離開倒計時。可取消或立即離開。競技場從不自動離開。",
  ["When a cast fails because the target is out of line of sight, its plate flashes with an 'Out of sight' tag (the game has no live line-of-sight check for addons)."] = "施法因目標不在視野中而失敗時，其名條閃爍並顯示“視野外”標籤（遊戲沒有為插件提供實時視野檢查）。",
  ["When a dungeon, raid or battleground invite pops, a countdown shows by the queue eye. Group Finder owns the timer; the minimap only shows it."] = "地城、團隊副本或戰場邀請彈出時，佇列眼睛旁顯示倒計時。計時器歸隊伍查詢器所有；小地圖只顯示它。",
  ["When a tracked cooldown glows."] = "追蹤的冷卻何時發光。",
  ["When an NPC colour meets threat"] = "NPC 顏色與仇恨衝突時",
  ["When an invite pops, a large Enter button appears. Phoenix never presses it for you."] = "邀請彈出時出現一個大的進入按鈕。Phoenix 從不替你點選。",
  ["When another player sends you a report, you get a prompt first (or it is refused)."] = "其他玩家向你傳送報告時，會先提示你（或拒絕）。",
  ["When cast history strips are shown."] = "何時顯示施法歷史條。",
  ["When casts come faster than the strip moves, it speeds up this much."] = "施法速度快於捲軸移動時，捲軸加速這麼多。",
  ["When sArena, sArena_Reloaded, sArenaReloaded, Gladius, GladiusEx is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "載入 sArena, sArena_Reloaded, sArenaReloaded, Gladius, GladiusEx 時，選擇由 Phoenix 還是該插件負責此功能。Phoenix 負責：另一個插件從下次載入起被禁用。另一個插件負責：此 Phoenix 模組保持關閉。",
  ["When someone types !keys in party chat, your key is posted through Phoenix announcements (Keystones topic decides where)."] = "有人在隊伍聊天中輸入 !keys 時，透過 Phoenix 通告發布你的鑰石（由“鑰石”主題決定位置）。",
  ["When the combat timer is shown."] = "何時顯示戰鬥計時器。",
  ["When the global cooldown bar is drawn."] = "何時繪製公共冷卻條。",
  ["When the language uses letters the game font lacks (Arabic, or Russian and Chinese on another client), Phoenix text uses a matching font from the media pack."] = "當語言使用遊戲字型缺少的字元時（阿拉伯語，或在其他客戶端上的俄語和中文），Phoenix 文字使用媒體包中匹配的字型。",
  ["When the warning sound plays."] = "何時播放警告音效。",
  ["When too many lines come at once, the extra ones are counted and shown as one \"+N more\" line."] = "一次來的行太多時，多餘的會被計數並顯示為一行“+N 條更多”。",
  ["When tooltips are hidden in combat, holding this key shows them anyway."] = "戰鬥中隱藏滑鼠提示時，按住此鍵仍會顯示。",
  ["When you are below the last visible row, your own row replaces it with your real rank."] = "當你位於最後一個可見行之下時，你自己的行以真實排名替換它。",
  ["When your group is ready or a Group Finder group invites you, the game icon flashes, a sound plays and a notice appears."] = "當你的隊伍就緒或隊伍查詢器中的隊伍邀請你時，遊戲圖示閃爍、播放音效並出現通知。",
  ["Where Mythic+ score colours come from in tooltips, Group Finder and data bars."] = "滑鼠提示、隊伍查詢器和資料條中傳奇鑰石分數顏色的來源。",
  ["Where announcements go. Only me prints a local line nobody else sees; Group picks party, raid or instance for you."] = "通告傳送的位置。“僅自己”輸出一行別人看不到的本地文字；“隊伍”自動選擇隊伍、團隊或副本頻道。",
  ["Where auto combat logging turns the log on. Works alongside recorder addons: a log they started is never stopped."] = "自動戰鬥日誌在哪裡開啟日誌。可與記錄插件同時使用：它們開啟的日誌從不會被停止。",
  ["Where each online friend is."] = "每位線上好友的位置。",
  ["Where each pet frame sits."] = "每個寵物框架的位置。",
  ["Where on the frame the private auras sit."] = "私有光環在框架上的位置。",
  ["Where text lines up in the area."] = "文字在區域中的對齊方式。",
  ["Where the M+ block sits"] = "傳奇鑰石模組的位置",
  ["Where the Phoenix panel sits next to the group finder."] = "Phoenix 面板在隊伍查詢器旁的位置。",
  ["Where the channel bar sits next to chat window 1."] = "頻道條在聊天視窗 1 旁的位置。",
  ["Where the clock sits on the minimap."] = "時鐘在小地圖上的位置。",
  ["Where the coordinates sit."] = "座標的位置。",
  ["Where the detached panel sits."] = "分離面板的位置。",
  ["Where the difficulty text sits."] = "難度文字的位置。",
  ["Where the dispel icons sit."] = "驅散圖示的位置。",
  ["Where the elite / rare icon sits on enemy plates. You can also drag it in the preview."] = "精英/稀有圖示在敵方名條上的位置。也可在預覽中拖動。",
  ["Where the game blocks addon chat (Mythic+, PvP, boss fights), a report waits and posts when the key, match or boss ends. Say and Yell ask you first."] = "遊戲阻止插件聊天的地方（傳奇鑰石、PvP、首領戰），報告會等待，在鑰石、比賽或首領戰結束時釋出。說和大喊會先詢問你。",
  ["Where the game's DR data is drawn. Needs DR tracking on."] = "遊戲遞減資料的繪製位置。需要開啟遞減追蹤。",
  ["Where the health text sits on enemy plates. You can also drag it in the preview."] = "生命值文字在敵方名條上的位置。也可在預覽中拖動。",
  ["Where the health text sits."] = "生命值文字的位置。",
  ["Where the m+ forces sits on enemy plates. You can also drag it in the preview."] = "傳奇鑰石部隊在敵方名條上的位置。也可在預覽中拖動。",
  ["Where the name sits on enemy plates. You can also drag it in the preview."] = "名字在敵方名條上的位置。也可在預覽中拖動。",
  ["Where the name sits on the frame."] = "名字在框架上的位置。",
  ["Where the name sits on the health bar."] = "名字在生命條上的位置。",
  ["Where the power bar sits."] = "能量條的位置。",
  ["Where the quest icon sits on enemy plates. You can also drag it in the preview."] = "任務圖示在敵方名條上的位置。也可在預覽中拖動。",
  ["Where the raid marker sits on enemy plates. You can also drag it in the preview."] = "團隊標記在敵方名條上的位置。也可在預覽中拖動。",
  ["Where the search panel sits."] = "搜尋面板的位置。",
  ["Where the window opens on screen. Dragging the window updates this."] = "視窗在螢幕上開啟的位置。拖動視窗會更新此項。",
  ["Where the zone name sits on the minimap."] = "區域名稱在小地圖上的位置。",
  ["Where to remind"] = "在哪裡提醒",
  ["Where to show"] = "在哪裡顯示",
  ["Where to switch"] = "在哪裡切換",
  ["Which action page (12 slots) bar 10 shows."] = "快捷列 10 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 2 shows."] = "快捷列 2 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 3 shows."] = "快捷列 3 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 4 shows."] = "快捷列 4 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 5 shows."] = "快捷列 5 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 6 shows."] = "快捷列 6 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 7 shows."] = "快捷列 7 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 8 shows."] = "快捷列 8 顯示哪個動作頁（12 個欄位）。",
  ["Which action page (12 slots) bar 9 shows."] = "快捷列 9 顯示哪個動作頁（12 個欄位）。",
  ["Which auras are shown."] = "顯示哪些光環。",
  ["Which auras this lane shows."] = "此通道顯示哪些光環。",
  ["Which battlegrounds use the countdown."] = "哪些戰場使用倒計時。",
  ["Which buffs are shown."] = "顯示哪些增益。",
  ["Which colour a listed NPC gets in combat."] = "列表中的 NPC 在戰鬥中使用哪種顏色。",
  ["Which corner of the conquest frame the panel sits in."] = "面板位於征服框架的哪個角落。",
  ["Which debuffs are shown."] = "顯示哪些減益。",
  ["Which errors the viewer lists first."] = "檢視器優先列出哪些錯誤。",
  ["Which minimap corner the Phoenix buttons start from."] = "Phoenix 按鈕從小地圖哪個角開始。",
  ["Which of your runs boss splits are compared with."] = "首領分段與你的哪次記錄對比。",
  ["Which scroll area shows it."] = "由哪個滾動區域顯示。",
  ["Which session the viewer shows first."] = "檢視器首先顯示哪個會話。",
  ["Which side of the bar the icon sits on."] = "圖示位於計量條的哪一側。",
  ["Which side of the cast bar the icon sits on."] = "圖示位於施法條的哪一側。",
  ["Which side of the frame the portrait sits on."] = "頭像位於框架的哪一側。",
  ["Which side the spec icon sits on."] = "專精圖示位於哪一側。",
  ["Which sound plays: four game sounds, then every sound in the media library (yours and other addons' shared sounds)."] = "播放哪個音效：四個遊戲音效，然後是媒體庫中的所有音效（你的以及其他插件共享的音效）。",
  ["Which tiers the pace line compares against."] = "節奏線與哪些層級比較。",
  ["Which way boss frames 2 to 5 are added."] = "首領框架 2 到 5 的新增方向。",
  ["Which way buttons fill a line; the popup opens and the bar docks on that side."] = "按鈕填充一行的方向；彈窗在該側開啟，條也停靠在該側。",
  ["Which way extra rows are added."] = "額外行的新增方向。",
  ["Which way extra rows of bar 1 are added."] = "快捷列 1 額外行的新增方向。",
  ["Which way extra rows of bar 10 are added."] = "快捷列 10 額外行的新增方向。",
  ["Which way extra rows of bar 2 are added."] = "快捷列 2 額外行的新增方向。",
  ["Which way extra rows of bar 3 are added."] = "快捷列 3 額外行的新增方向。",
  ["Which way extra rows of bar 4 are added."] = "快捷列 4 額外行的新增方向。",
  ["Which way extra rows of bar 5 are added."] = "快捷列 5 額外行的新增方向。",
  ["Which way extra rows of bar 6 are added."] = "快捷列 6 額外行的新增方向。",
  ["Which way extra rows of bar 7 are added."] = "快捷列 7 額外行的新增方向。",
  ["Which way extra rows of bar 8 are added."] = "快捷列 8 額外行的新增方向。",
  ["Which way extra rows of bar 9 are added."] = "快捷列 9 額外行的新增方向。",
  ["Which way lines scroll."] = "行滾動的方向。",
  ["Which way new icons are added on a row."] = "新圖示在一行中的新增方向。",
  ["Which way older casts move."] = "舊施法移動的方向。",
  ["Which way the buttons of bar 1 run."] = "快捷列 1 按鈕的排列方向。",
  ["Which way the buttons of bar 10 run."] = "快捷列 10 按鈕的排列方向。",
  ["Which way the buttons of bar 2 run."] = "快捷列 2 按鈕的排列方向。",
  ["Which way the buttons of bar 3 run."] = "快捷列 3 按鈕的排列方向。",
  ["Which way the buttons of bar 4 run."] = "快捷列 4 按鈕的排列方向。",
  ["Which way the buttons of bar 5 run."] = "快捷列 5 按鈕的排列方向。",
  ["Which way the buttons of bar 6 run."] = "快捷列 6 按鈕的排列方向。",
  ["Which way the buttons of bar 7 run."] = "快捷列 7 按鈕的排列方向。",
  ["Which way the buttons of bar 8 run."] = "快捷列 8 按鈕的排列方向。",
  ["Which way the buttons of bar 9 run."] = "快捷列 9 按鈕的排列方向。",
  ["While Pulse shows boss bars, sets the game's own timeline to its empty view. Your previous view comes back when you turn this off."] = "Pulse 顯示首領條時，將遊戲自帶時間軸設為空檢視。關閉此項時恢復你之前的檢視。",
  ["While Spark is on, the game's combat state, reactive, honor and reputation popups are off. Restored when this or Spark is off."] = "Spark 開啟時，關閉遊戲的戰鬥狀態、反應、榮譽和聲望彈出提示。此項或 Spark 關閉時恢復。",
  ["While Spark is on, the game's own damage and healing numbers over enemies are off. Your old setting comes back when this or Spark is off."] = "Spark 開啟時，關閉遊戲在敵人頭上顯示的傷害和治療數字。此項或 Spark 關閉時恢復你原來的設定。",
  ["While Spark is on, the game's own text over your character is off. Restored when this or Spark is off."] = "Spark 開啟時，關閉遊戲在你角色頭上顯示的文字。此項或 Spark 關閉時恢復。",
  ["While a key runs, Ascent's Mythic+ block sits at the top of the tracker (Ascent owns the timer)."] = "鑰石進行時，Ascent 的傳奇鑰石模組位於追蹤頂部（計時器由 Ascent 負責）。",
  ["While a report waits, it also opens in the copy box so you can paste it yourself."] = "報告等待傳送時，也會在複製框中開啟，方便你自己貼上。",
  ["While a tooltip shows IDs, this key opens them in the copy box. It is only taken while IDs are on screen, and never over a key you bound yourself. Empty turns it off."] = "滑鼠提示顯示 ID 時，此鍵在複製框中開啟它們。僅在 ID 顯示於螢幕時佔用，且不會覆蓋你自己繫結的按鍵。留空則關閉。",
  ["While an achievement ID setting is 0, Phoenix looks up the season's title achievement in the game's list (once per season) and reads its progress."] = "成就 ID 設定為 0 時，Phoenix 在遊戲列表中查詢本賽季的頭銜成就（每賽季一次）並讀取其進度。",
  ["While the developer profiler has samples, each module page shows how much time that module took."] = "開發者效能分析器有采樣時，每個模組頁面會顯示該模組耗時。",
  ["While you fish: a bar with the time left on the cast and a catch counter for this session. Off by default."] = "釣魚時：顯示施放剩餘時間的條和本次會話的釣獲計數。預設關閉。",
