  ["Window width"] = "視窗寬度",
  ["Windows 2-4 dock to the previous one, so moving window 1 moves the set."] = "視窗 2-4 停靠到前一個視窗，移動視窗 1 會移動整組。",
  ["Windows open where you last left them. Off: they move only until closed."] = "視窗在你上次離開的位置開啟。關閉：僅在關閉前保持移動位置。",
  ["Wins needed when Phoenix counts them itself."] = "Phoenix 自行計數時所需的勝場。",
  ["Wins toward each title. Uses the game's own achievement count when the season has one; otherwise Phoenix counts wins taken at or above the title rating."] = "每個頭銜的勝場。如果本賽季有遊戲成就計數則使用它；否則 Phoenix 統計在頭銜評級或以上取得的勝場。",
  ["Wisdom"] = "智慧",
  ["With BigWigs loaded, adds a \"Phoenix UI\" bar style you can pick in BigWigs' bar options."] = "載入 BigWigs 時，新增可在 BigWigs 計時條選項中選擇的“Phoenix UI”樣式。",
  ["With FrameSort loaded, the arena numbers follow its sorted enemy order (matching its EnemyFrame macros)."] = "載入 FrameSort 時，競技場編號遵循其排序的敵人順序（與其 EnemyFrame 巨集一致）。",
  ["With In game only, also leave out friends playing a different version of World of Warcraft."] = "選擇“僅遊戲中”時，也排除正在玩其他版本魔獸世界的好友。",
  ["With Masque loaded, cast icons use the skin you pick for \"Phoenix UI: Cast History\" in Masque."] = "載入 Masque 時，施法圖示使用你在 Masque 中為“Phoenix UI: Cast History”選擇的皮膚。",
  ["With Raider.IO loaded, adds the leader's Raider.IO score to each row (filter words rio and riomain work either way)."] = "載入 Raider.IO 時，為每行新增隊長的 Raider.IO 分數（過濾詞 rio 和 riomain 無論如何都可用）。",
  ["With several elements selected, dragging one moves them all."] = "選中多個元素時，拖動其中一個會移動全部。",
  ["Words for the dungeons, raids or delves to keep (see the word list in the help panel; the season's words are added live). Empty keeps all."] = "要保留的地城、團隊副本或探究的詞（見幫助面板中的詞表；本賽季的詞實時新增）。留空則全部保留。",
  ["Words never hidden in paths"] = "路徑中永不隱藏的詞",
  ["World label colour"] = "世界標籤顏色",
  ["World loot list"] = "世界拾取列表",
  ["World markers"] = "世界標記",
  ["World: Achievement ID"] = "世界：成就 ID",
  ["World: Area POI ID"] = "世界：區域興趣點 ID",
  ["World: Criteria ID"] = "世界：條件 ID",
  ["World: Currency ID"] = "世界：貨幣 ID",
  ["World: NPC ID"] = "世界：NPC ID",
  ["World: Object ID"] = "世界：物體 ID",
  ["World: Quest ID"] = "世界：任務 ID",
  ["World: Vignette ID"] = "世界：稀有標記 ID",
  ["Write every readable number in thousands, millions or billions."] = "將每個可讀數字寫成千、百萬或十億。",
  ["Writes 1, 2, 3 beside each frame (matches /target arena1)."] = "在每個框架旁寫 1、2、3（與 /target arena1 對應）。",
  ["Writes 1., 2., 3. before names."] = "在名字前寫 1.、2.、3.。",
  ["Writes 1/2, 1/4 or immune when the game's values are readable (hidden values show icon and swipe only)."] = "遊戲數值可讀時寫 1/2、1/4 或免疫（隱藏數值只顯示圖示和遮罩）。",
  ["Writes Blizzard's own server-side minimum rating filter. Your previous Blizzard filter is saved and put back when this returns to 0."] = "寫入暴雪自己的伺服器端最低評級過濾。你之前的暴雪過濾會被儲存，並在此項歸 0 時恢復。",
  ["Writes W or L for each round once the game shows the round count plainly (it is hidden during play)."] = "遊戲明確顯示回合數後，為每回合寫 W 或 L（比賽中隱藏）。",
  ["Writes the boss name (or Combat) before the time."] = "在時間前寫首領名字（或“戰鬥”）。",
  ["Writes the buff name under each icon."] = "在每個圖示下寫增益名稱。",
  ["Writes the item level on equippable items."] = "在可裝備物品上寫物品等級。",
  ["Writes the pet's name on its bar (the game may hide some)."] = "在寵物的條上寫其名字（遊戲可能隱藏部分）。",
  ["Writes the quest level before the title."] = "在標題前寫任務等級。",
  ["XP / reputation / honor bar"] = "經驗/聲望/榮譽條",
  ["XP / reputation bar"] = "經驗/聲望條",
  ["Yellow below (seconds)"] = "低於此值變黃（秒）",
  ["You and each party member get your own frame that you can move anywhere in Studio, instead of one row. Sorting by role does not apply while this is on."] = "你和每位隊員都有自己的框架，可在 Studio 中移動到任意位置，而不是一行。開啟時按職責排序不生效。",
  ["Your character name is replaced by [player] as a whole word, and GUIDs keep only their kind, before anything is shared or uploaded."] = "在共享或上傳任何內容前，你的角色名會作為完整單詞替換為 [player]，GUID 只保留其型別。",
  ["Your damage"] = "你的傷害",
  ["Your damage: area"] = "你的傷害：區域",
  ["Your damage: colour"] = "你的傷害：顏色",
  ["Your damage: message"] = "你的傷害：訊息",
  ["Your damage: sound"] = "你的傷害：音效",
  ["Your debuff timers change colour in the last 30 % of their duration, when refreshing loses nothing."] = "你的減益計時在持續時間最後 30 % 時變色，此時重新整理不會損失任何時間。",
  ["Your debuffs"] = "你的減益",
  ["Your debuffs on the enemy, above the plate."] = "敵人身上你的減益，位於名條上方。",
  ["Your debuffs: how many"] = "你的減益：數量",
  ["Your debuffs: icon size"] = "你的減益：圖示大小",
  ["Your debuffs: which ones"] = "你的減益：哪些",
  ["Your drag order (Edit mode)."] = "你的拖動順序（編輯模式）。",
  ["Your focus target's cast bar with your interrupt's cooldown beside it. Move it in Studio."] = "專注目標的施法條，旁邊顯示你打斷的冷卻。在 Studio 中移動它。",
  ["Your heals"] = "你的治療",
  ["Your heals: area"] = "你的治療：區域",
  ["Your heals: colour"] = "你的治療：顏色",
  ["Your heals: message"] = "你的治療：訊息",
  ["Your heals: sound"] = "你的治療：音效",
  ["Your last rated match and how much it moved your rating."] = "你上一場評級比賽及其對評級的影響。",
  ["Your lockout on raid rows"] = "團隊副本行上的你的鎖定",
  ["Your misses"] = "你的未命中",
  ["Your misses: area"] = "你的未命中：區域",
  ["Your misses: colour"] = "你的未命中：顏色",
  ["Your misses: message"] = "你的未命中：訊息",
  ["Your misses: sound"] = "你的未命中：音效",
  ["Your note after each friend in the search panel."] = "搜尋面板中每位好友後的你的備註。",
  ["Your own categories, one per line as Name|rule, checked before the built-in ones. Example: Sets: PvP|set ~ PvP and ilvl >= 640. Fields: type, subtype, ilvl, quality, name, id, bound, expansion, slot, count, set, keystone."] = "你自己的分類，每行一個，格式為 Name|rule，在內建分類之前檢查。示例：Sets: PvP|set ~ PvP and ilvl >= 640。欄位：type、subtype、ilvl、quality、name、id、bound、expansion、slot、count、set、keystone。",
  ["Your own lines for casts, auras and combat. Build them with /pui spark trigger."] = "你自己的施法、光環和戰鬥行。用 /pui spark trigger 建立。",
