  ["Order of the buttons on auto item bar 1."] = "自動物品條 1 上按鈕的順序。",
  ["Order of the buttons on auto item bar 2."] = "自動物品條 2 上按鈕的順序。",
  ["Order of the buttons on auto item bar 3."] = "自動物品條 3 上按鈕的順序。",
  ["Order of the buttons on auto item bar 4."] = "自動物品條 4 上按鈕的順序。",
  ["Order of the buttons on auto item bar 5."] = "自動物品條 5 上按鈕的順序。",
  ["Show auto item bar 1 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、從不，或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示自動物品條 1。",
  ["Show auto item bar 2 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、從不，或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示自動物品條 2。",
  ["Show auto item bar 3 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、從不，或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示自動物品條 3。",
  ["Show auto item bar 4 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、從不，或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示自動物品條 4。",
  ["Show auto item bar 5 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、從不，或僅在你選擇的內容、戰鬥狀態、隊伍和專精中顯示自動物品條 5。",
  ["Shows cooldown swipes on auto item bar 1."] = "在自動物品條 1 上顯示冷卻轉圈。",
  ["Shows cooldown swipes on auto item bar 2."] = "在自動物品條 2 上顯示冷卻轉圈。",
  ["Shows cooldown swipes on auto item bar 3."] = "在自動物品條 3 上顯示冷卻轉圈。",
  ["Shows cooldown swipes on auto item bar 4."] = "在自動物品條 4 上顯示冷卻轉圈。",
  ["Shows cooldown swipes on auto item bar 5."] = "在自動物品條 5 上顯示冷卻轉圈。",
  ["Shows how many of each item you carry on auto item bar 1."] = "在自動物品條 1 上顯示你攜帶的每種物品數量。",
  ["Shows how many of each item you carry on auto item bar 2."] = "在自動物品條 2 上顯示你攜帶的每種物品數量。",
  ["Shows how many of each item you carry on auto item bar 3."] = "在自動物品條 3 上顯示你攜帶的每種物品數量。",
  ["Shows how many of each item you carry on auto item bar 4."] = "在自動物品條 4 上顯示你攜帶的每種物品數量。",
  ["Shows how many of each item you carry on auto item bar 5."] = "在自動物品條 5 上顯示你攜帶的每種物品數量。",
  ["The battle res button shows the group's shared charges and recharge timer (keys and boss fights) instead of the spell's own cooldown."] = "戰復按鈕顯示團隊共享的次數和充能計時（鑰石和首領戰），而非法術自身的冷卻。",
  ["Tick the categories each auto item bar fills itself with, from your bags and gear. Rows run top to bottom in the order the buttons appear."] = "勾選每個自動物品條從你的背包和裝備中自動填充的類別。各行從上到下即按鈕出現的順序。",
  ["Turns auto item bar 1 on. It fills itself with the categories ticked for it."] = "開啟自動物品條 1。它會用為其勾選的類別自動填充。",
  ["Turns auto item bar 2 on. It fills itself with the categories ticked for it."] = "開啟自動物品條 2。它會用為其勾選的類別自動填充。",
  ["Turns auto item bar 3 on. It fills itself with the categories ticked for it."] = "開啟自動物品條 3。它會用為其勾選的類別自動填充。",
  ["Turns auto item bar 4 on. It fills itself with the categories ticked for it."] = "開啟自動物品條 4。它會用為其勾選的類別自動填充。",
  ["Turns auto item bar 5 on. It fills itself with the categories ticked for it."] = "開啟自動物品條 5。它會用為其勾選的類別自動填充。",
  ["Which way auto item bar 1 adds buttons."] = "自動物品條 1 新增按鈕的方向。",
  ["Which way auto item bar 2 adds buttons."] = "自動物品條 2 新增按鈕的方向。",
  ["Which way auto item bar 3 adds buttons."] = "自動物品條 3 新增按鈕的方向。",
  ["Which way auto item bar 4 adds buttons."] = "自動物品條 4 新增按鈕的方向。",
  ["Which way auto item bar 5 adds buttons."] = "自動物品條 5 新增按鈕的方向。",
  ["Masque: Cooldown Manager icons"] = "Masque：冷卻管理器圖示",
  ["Masque: action bars"] = "Masque：快捷列",
  ["Masque: auto item bars"] = "Masque：自動物品條",
  ["Masque: stance, pet, vehicle and item bar"] = "Masque：姿態列、寵物列、載具與物品條",
  ["With Masque installed, Cooldown Manager icons use the \"Phoenix UI: Cooldown Manager\" Masque group."] = "安裝 Masque 後，冷卻管理器圖示使用 Masque 中的「Phoenix UI: Cooldown Manager」群組。",
  ["With Masque installed, Phoenix action bars use the skin you pick for each \"Phoenix UI: Action bar\" group in Masque."] = "安裝 Masque 後，Phoenix 快捷列使用你在 Masque 中為每個「Phoenix UI: Action bar」群組選擇的外觀。",
  ["With Masque installed, each auto item bar uses its own Masque group."] = "安裝 Masque 後，每個自動物品條使用各自的 Masque 群組。",
  ["With Masque installed, the stance, pet, vehicle exit and item bars use their Masque groups."] = "安裝 Masque 後，姿態列、寵物列、離開載具按鈕和物品條使用各自的 Masque 群組。",
  ["Also track your own cooldowns."] = "同時追蹤你自己的冷卻。",
  ["Attach each member's icons to their Phoenix party frame, or show one movable list. Without Phoenix party frames the list is used."] = "將每名成員的圖示附在其 Phoenix 隊伍框架上，或顯示為一個可移動的列表。沒有 Phoenix 隊伍框架時使用列表。",
  ["Battle res"] = "戰復",
  ["Big damage cooldowns"] = "大型爆發技能",
  ["Bloodlust / Heroism"] = "嗜血 / 英勇",
  ["Distance between the party frame and its icons."] = "隊伍框架與其圖示之間的距離。",
  ["Each member's class interrupt shows from the start; other spells appear once that member casts them."] = "每名成員的職業斷法從一開始就顯示；其他法術在該成員施放後出現。",
  ["Gap between party cooldown icons."] = "隊伍冷卻圖示之間的間隔。",
  ["Gap from the frame"] = "與框架的間距",
  ["Group defensives"] = "團隊減傷",
  ["Icons per member"] = "每名成員圖示數",
  ["Include yourself"] = "包括你自己",
  ["Interrupts"] = "斷法",
  ["Most icons shown for one party member."] = "單個隊伍成員最多顯示的圖示數。",
  ["Party cooldowns"] = "隊伍冷卻",
  ["Party interrupts, defensives, group cooldowns, battle res and Bloodlust as icons on the party frames or in a list (an OmniCD-style tracker)."] = "隊伍的斷法、減傷、團隊技能、戰復和嗜血，以圖示顯示在隊伍框架上或列表中（OmniCD 風格的追蹤器）。",
  ["Personal defensives"] = "個人減傷",
  ["Show interrupts before first use"] = "首次使用前顯示斷法",
  ["Side of the party frame"] = "隊伍框架的哪一側",
  ["Size of the party cooldown icons."] = "隊伍冷卻圖示的大小。",
  ["Tracks Bloodlust, Heroism, Time Warp and Fury of the Aspects."] = "追蹤 Bloodlust、Heroism、Time Warp 和 Fury of the Aspects。",
  ["Tracks battle res spells (Rebirth, Raise Ally, Soulstone, Intercession)."] = "追蹤戰復法術（Rebirth、Raise Ally、Soulstone、Intercession）。",
  ["Tracks big damage cooldowns such as Combustion, Avatar and Celestial Alignment."] = "追蹤大型爆發技能，例如 Combustion、Avatar 和 Celestial Alignment。",
  ["Tracks group defensives such as Rallying Cry, Spirit Link Totem and Darkness."] = "追蹤團隊減傷，例如 Rallying Cry、Spirit Link Totem 和 Darkness。",
  ["Tracks party interrupts (Kick, Pummel, Counterspell, Wind Shear and the rest)."] = "追蹤隊伍斷法（Kick、Pummel、Counterspell、Wind Shear 等）。",
  ["Tracks personal defensives such as Ice Block, Divine Shield and Cloak of Shadows."] = "追蹤個人減傷，例如 Ice Block、Divine Shield 和 Cloak of Shadows。",
  ["Where icons go"] = "圖示位置",
  ["Which side of the party frame the icons sit on."] = "圖示位於隊伍框架的哪一側。",
  ["A compact, movable list of group loot rolls with item level, a timer bar and Need / Greed / Transmog / Pass buttons, in place of the game's roll frames."] = "緊湊、可移動的隊伍拾取擲骰列表，帶物品等級、計時條和需求 / 貪婪 / 塑形 / 放棄按鈕，取代遊戲內建的擲骰框架。",
  ["Height of each loot roll row (the icon and buttons follow)."] = "每行拾取擲骰的高度（圖示和按鈕隨之調整）。",
  ["Keep Blizzard's roll frames"] = "保留暴雪的擲骰框架",
  ["New rolls grow upwards"] = "新的擲骰向上增長",
  ["Roll height"] = "擲骰行高度",
  ["Roll width"] = "擲骰行寬度",
  ["Show the game's own loot roll frames as well (Phoenix rolls stay)."] = "同時顯示遊戲內建的拾取擲骰框架（Phoenix 擲骰保留）。",
  ["Stack rolls upwards from the anchor instead of downwards."] = "從錨點向上堆疊擲骰，而不是向下。",
  ["Width of each loot roll row."] = "每行拾取擲骰的寬度。",
  ["Also use the focus key on Phoenix party and raid frames (leave off if click casting uses that key)."] = "在 Phoenix 隊伍和團隊框架上也使用專注鍵（如果點擊施法佔用了該鍵請保持關閉）。",
  ["Auto item bars: hearthstone toys"] = "自動物品條：爐石玩具",
  ["Auto item bars: this season's teleports only"] = "自動物品條：僅本賽季傳送",
  ["Focus key"] = "專注鍵",
  ["Focus key mouse button"] = "專注鍵滑鼠按鍵",
  ["Focus key on party and raid frames"] = "隊伍和團隊框架上的專注鍵",
  ["For a reputation past its maximum, the bar and the reputation block show paragon progress toward the next reward chest (a + marks a chest waiting)."] = "對已滿級的聲望，進度條和聲望區塊顯示典範進度直到下一個獎勵寶箱（+ 表示有寶箱待領取）。",
